-- =====================================================================================================
-- Dawak (دواك) — full database script in ONE file: extensions, enums, all 17 tables, indexes, triggers,
-- row-level security, grants, RPC functions (pharmacy list, availability requests "ask nearby", orders,
-- POS, public search, dashboard) and the private licence-documents storage bucket.
--
-- Generated by concatenating the nine files of supabase/migrations/ in order (do not edit by hand; edit
-- the migrations and regenerate with `python3 tool/build_full_sql.py`).
--
-- HOW TO USE (new, EMPTY Supabase project): Dashboard -> SQL Editor -> New query -> paste this whole file -> Run.
-- Do NOT run it twice on the same database: the objects are created without IF NOT EXISTS on purpose.
--
-- AFTER RUNNING (see docs/release_checklist.md section 1):
--   * Enable the pg_cron extension and schedule the three maintenance jobs (they are NOT created here):
--       private.expire_all_reservations()               every 5 minutes
--       private.advance_all_availability_requests()     every minute
--       delete from public.idempotency_keys ...         daily
--   * Optional: supabase/seed.sql (sample categories + medicines) and supabase/dev/bootstrap_first_admin.sql.
--
-- Verified only on a local PostgreSQL 16 with a stub of Supabase's auth/storage objects (see docs/progress.md);
-- never run on a real Supabase project.
-- =====================================================================================================


-- ====================================================================================================
-- PART 20261011000001_foundation.sql
-- ====================================================================================================
-- Dawak foundation: schemas, extensions, enums and pure (table-independent) helpers.

create schema if not exists extensions;
create extension if not exists pg_trgm with schema extensions;
create extension if not exists pgcrypto with schema extensions;

-- `private` holds helpers that must never be exposed through the API.
create schema if not exists private;

-- PostgreSQL grants EXECUTE on every new function to PUBLIC by default, and
-- `ALTER DEFAULT PRIVILEGES IN SCHEMA ... REVOKE` cannot remove that built-in default.
-- Revoking it globally (for the role running migrations) makes a forgotten GRANT fail closed.
alter default privileges revoke execute on functions from public;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.user_role as enum ('customer', 'pharmacist', 'admin');
create type public.account_status as enum ('active', 'suspended');
create type public.approval_status as enum ('pending', 'approved', 'rejected', 'suspended');
create type public.member_role as enum ('owner', 'manager', 'cashier');
create type public.member_status as enum ('active', 'suspended', 'removed');
create type public.catalog_status as enum ('pending', 'approved', 'rejected', 'archived');
create type public.order_status as enum (
  'pending', 'accepted', 'ready_for_pickup', 'completed', 'rejected', 'cancelled', 'expired'
);
-- Availability requests ("ask the pharmacies nearby"), see docs/availability_design.md.
create type public.request_status as enum ('open', 'closed', 'expired');
create type public.request_answer as enum ('available', 'unavailable');
create type public.report_status as enum ('open', 'in_review', 'resolved', 'dismissed');
create type public.report_target as enum ('pharmacy', 'medicine', 'order', 'app', 'other');
create type public.payment_method as enum ('cash');

-- ---------------------------------------------------------------------------
-- Server-side configuration (change via a new migration)
-- ---------------------------------------------------------------------------
create function private.cfg_int(p_key text) returns integer
language sql immutable parallel safe as $$
  select case p_key
    when 'reservation_hours'         then 24    -- how long a pharmacy promises to hold an accepted order
    when 'fresh_days'                then 7     -- listing confirmed within this many days is "recent"
    when 'listing_max_age_days'      then 30    -- listings not confirmed for longer are hidden from customers
    when 'max_pending_orders'        then 5
    when 'max_orders_per_hour'       then 10
    when 'max_customer_qty_per_item' then 10
    when 'max_order_lines'           then 20
    when 'max_pos_qty_per_item'      then 999
    when 'max_pos_lines'             then 100
    when 'request_ttl_minutes'       then 60    -- life of an availability request
    when 'request_wait_minutes'      then 3     -- silence before the radius is widened
    when 'request_max_step'          then 4     -- radius steps, see request_radius_km
    when 'max_open_requests'         then 3     -- open requests per customer
    when 'max_requests_per_hour'     then 10     -- requests created per customer per hour
    when 'max_request_targets'       then 25    -- pharmacies notified per request (nearest first)
    when 'request_dedupe_minutes'    then 15    -- same medicine, same spot: reuse the open request
    when 'max_import_items'          then 500   -- rows per bulk import call
    when 'max_match_names'           then 100   -- names per catalogue-matching call
  end
$$;

-- ---------------------------------------------------------------------------
-- Error signalling: business failures are P0001 with MESSAGE = machine code.
-- ---------------------------------------------------------------------------
create function private.fail(p_code text, p_detail jsonb default null) returns void
language plpgsql as $$
begin
  raise exception using
    errcode = 'P0001',
    message = p_code,
    detail = coalesce(p_detail::text, '');
end
$$;

-- ---------------------------------------------------------------------------
-- Text helpers
-- ---------------------------------------------------------------------------
-- Normalised search text: lowercase, strip tashkeel/tatweel, fold alef/ya/ta-marbuta/hamza
-- variants and Persian kaf/ya, map Arabic-Indic and Persian digits to ASCII.
-- from: أ إ آ ٱ ى ة ؤ ئ ک ی  + ٠-٩ + ۰-۹   (10 + 10 + 10 = 30 characters)
-- to  : ا ا ا ا ي ه و ي ك ي  + 0-9 + 0-9
create function private.normalize_search(p_text text) returns text
language sql immutable parallel safe as $$
  select btrim(
    regexp_replace(
      translate(
        lower(regexp_replace(coalesce(p_text, ''), '[ً-ٰٟـ]', '', 'g')),
        'أإآٱىةؤئکی٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹',
        'اااايهويكي01234567890123456789'
      ),
      '\s+', ' ', 'g'
    )
  )
$$;

create function private.like_escape(p_text text) returns text
language sql immutable parallel safe as $$
  select replace(replace(replace(p_text, '\', '\\'), '%', '\%'), '_', '\_')
$$;

-- Returns a normalised phone (ASCII digits, optional leading +, 7-15 digits) or NULL.
create function private.clean_phone(p_text text) returns text
language sql immutable parallel safe as $$
  select case when s.v ~ '^\+?[0-9]{7,15}$' then s.v else null end
  from (
    select regexp_replace(
             translate(coalesce(p_text, ''), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789'),
             '[\s\-\(\)\.]', '', 'g'
           ) as v
  ) s
$$;

-- Validates and trims a required/optional text input.
create function private.req_text(
  p_value text, p_field text, p_min integer, p_max integer, p_required boolean default true
) returns text
language plpgsql immutable as $$
declare
  v text := btrim(coalesce(p_value, ''));
begin
  if v = '' then
    if p_required then
      perform private.fail('invalid_input', jsonb_build_object('field', p_field, 'reason', 'required'));
    end if;
    return null;
  end if;
  if char_length(v) < p_min or char_length(v) > p_max then
    perform private.fail('invalid_input', jsonb_build_object('field', p_field, 'reason', 'length'));
  end if;
  return v;
end
$$;

-- ---------------------------------------------------------------------------
-- Domain helpers
-- ---------------------------------------------------------------------------
create function private.generate_order_ref() returns text
language sql volatile as $$
  select 'DWK-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))
$$;

create function private.order_transition_allowed(p_from public.order_status, p_to public.order_status)
returns boolean
language sql immutable as $$
  select (p_from, p_to) in (
    ('pending'::public.order_status,          'accepted'::public.order_status),
    ('pending'::public.order_status,          'rejected'::public.order_status),
    ('pending'::public.order_status,          'cancelled'::public.order_status),
    ('accepted'::public.order_status,         'ready_for_pickup'::public.order_status),
    ('accepted'::public.order_status,         'cancelled'::public.order_status),
    ('accepted'::public.order_status,         'expired'::public.order_status),
    ('ready_for_pickup'::public.order_status, 'completed'::public.order_status),
    ('ready_for_pickup'::public.order_status, 'cancelled'::public.order_status),
    ('ready_for_pickup'::public.order_status, 'expired'::public.order_status),
    ('expired'::public.order_status,          'accepted'::public.order_status),
    ('expired'::public.order_status,          'cancelled'::public.order_status)
  )
$$;

-- How fresh a pharmacy's confirmation is: 'recent' (<= fresh_days) or 'old'.
create function private.listing_freshness(p_confirmed timestamptz) returns text
language sql stable as $$
  select case
    when p_confirmed >= now() - make_interval(days => private.cfg_int('fresh_days')) then 'recent'
    else 'old'
  end
$$;

-- ---------------------------------------------------------------------------
-- Geography (no PostGIS needed: great-circle distance on a sphere is plenty for "within N km")
-- ---------------------------------------------------------------------------
create function private.distance_km(
  p_lat1 double precision, p_lon1 double precision, p_lat2 double precision, p_lon2 double precision
) returns double precision
language sql immutable parallel safe as $$
  select 2 * 6371.0088 * asin(least(1.0, sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2) +
    cos(radians(p_lat1)) * cos(radians(p_lat2)) * power(sin(radians(p_lon2 - p_lon1) / 2), 2)
  )))
$$;

-- Radius (km) of each widening step of an availability request.
create function private.request_radius_km(p_step integer) returns double precision
language sql immutable parallel safe as $$
  select case p_step when 1 then 1.0 when 2 then 3.0 when 3 then 5.0 when 4 then 10.0 end
$$;

-- Validates a coordinate pair (both present, inside the valid ranges, not the (0,0) placeholder).
create function private.check_location(p_lat double precision, p_lng double precision) returns void
language plpgsql immutable as $$
begin
  if p_lat is null or p_lng is null
     or p_lat <> p_lat or p_lng <> p_lng                       -- NaN
     or p_lat not between -90 and 90 or p_lng not between -180 and 180
     or (p_lat = 0 and p_lng = 0) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'location'));
  end if;
end
$$;

-- Start of a local calendar day as timestamptz.
create function private.local_day_start(p_day date, p_tz text) returns timestamptz
language sql immutable as $$
  select (p_day::timestamp) at time zone p_tz
$$;

-- ====================================================================================================
-- PART 20261011000002_core_tables.sql
-- ====================================================================================================
-- Dawak tables. RLS and grants are applied in a later migration.

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default '' check (char_length(display_name) <= 80),
  phone text check (phone is null or phone ~ '^\+?[0-9]{7,15}$'),
  role public.user_role not null default 'customer',
  account_status public.account_status not null default 'active',
  suspended_reason text check (suspended_reason is null or char_length(suspended_reason) <= 300),
  locale text not null default 'ar' check (locale in ('ar', 'en')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.pharmacies (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete restrict,
  name text not null check (char_length(btrim(name)) between 2 and 120),
  phone text not null check (phone ~ '^\+?[0-9]{7,15}$'),
  show_phone_publicly boolean not null default true,
  address_line text not null check (char_length(btrim(address_line)) between 3 and 250),
  neighborhood text not null default '' check (char_length(neighborhood) <= 100),
  city text not null check (char_length(btrim(city)) between 2 and 100),
  directions text check (directions is null or char_length(directions) <= 500),
  -- Where the shop is (device GPS at the shop, or a pasted map link). Needed for "nearest first" and for
  -- availability requests; the pharmacy's location is public information (customers see it on the map link).
  latitude double precision check (latitude is null or latitude between -90 and 90),
  longitude double precision check (longitude is null or longitude between -180 and 180),
  opening_hours jsonb not null default '{}'::jsonb check (jsonb_typeof(opening_hours) = 'object'),
  currency text not null default 'SYP' check (currency in ('SYP', 'USD')),
  timezone text not null default 'Asia/Damascus' check (timezone in ('Asia/Damascus')),
  approval_status public.approval_status not null default 'pending',
  status_reason text check (status_reason is null or char_length(status_reason) <= 500),
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  submitted_at timestamptz not null default now(),
  is_listed boolean not null default false,
  license_document_path text check (license_document_path is null or char_length(license_document_path) <= 300),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pharmacies_location_pair check ((latitude is null) = (longitude is null)),
  constraint pharmacies_listed_requires_approval check (not is_listed or approval_status = 'approved'),
  constraint pharmacies_reason_required check (
    approval_status not in ('rejected', 'suspended') or coalesce(btrim(status_reason), '') <> ''
  )
);
-- MVP: one pharmacy per owner account.
create unique index pharmacies_one_per_owner on public.pharmacies (owner_id);
create index pharmacies_public_idx on public.pharmacies (city) where approval_status = 'approved' and is_listed;
create index pharmacies_status_idx on public.pharmacies (approval_status, submitted_at);
create index pharmacies_geo_idx on public.pharmacies (latitude, longitude)
  where approval_status = 'approved' and is_listed and latitude is not null;

create table public.pharmacy_members (
  pharmacy_id uuid not null references public.pharmacies (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  role public.member_role not null,
  status public.member_status not null default 'active',
  created_at timestamptz not null default now(),
  primary key (pharmacy_id, user_id)
);
create index pharmacy_members_user_idx on public.pharmacy_members (user_id) where status = 'active';

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------
create table public.medicine_categories (
  id uuid primary key default gen_random_uuid(),
  name_ar text not null check (char_length(btrim(name_ar)) between 1 and 80),
  name_en text check (name_en is null or char_length(name_en) <= 80),
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);
create unique index medicine_categories_name_ar_uq on public.medicine_categories (private.normalize_search(name_ar));

create table public.medicines (
  id uuid primary key default gen_random_uuid(),
  category_id uuid references public.medicine_categories (id) on delete set null,
  name_ar text check (name_ar is null or char_length(name_ar) <= 160),
  name_en text check (name_en is null or char_length(name_en) <= 160),
  brand_name text check (brand_name is null or char_length(brand_name) <= 160),
  active_ingredient text check (active_ingredient is null or char_length(active_ingredient) <= 200),
  strength text check (strength is null or char_length(strength) <= 60),
  dosage_form text check (dosage_form is null or char_length(dosage_form) <= 60),
  package_description text check (package_description is null or char_length(package_description) <= 200),
  catalog_status public.catalog_status not null default 'pending',
  proposed_by uuid references public.profiles (id) on delete set null,
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  search_text text generated always as (
    private.normalize_search(
      coalesce(name_ar, '') || ' ' || coalesce(name_en, '') || ' ' || coalesce(brand_name, '') || ' ' ||
      coalesce(active_ingredient, '') || ' ' || coalesce(strength, '') || ' ' || coalesce(dosage_form, '')
    )
  ) stored,
  dedupe_key text generated always as (
    private.normalize_search(
      coalesce(name_ar, '') || '|' || coalesce(name_en, '') || '|' || coalesce(brand_name, '') || '|' ||
      coalesce(strength, '') || '|' || coalesce(dosage_form, '') || '|' || coalesce(package_description, '')
    )
  ) stored,
  constraint medicines_has_name check (coalesce(btrim(name_ar), '') <> '' or coalesce(btrim(name_en), '') <> '')
);
-- No duplicate live catalogue entries (rejected/archived rows may be re-proposed).
create unique index medicines_dedupe_uq on public.medicines (dedupe_key)
  where catalog_status in ('pending', 'approved');
create index medicines_search_trgm on public.medicines using gin (search_text extensions.gin_trgm_ops);
create index medicines_status_idx on public.medicines (catalog_status);
create index medicines_category_idx on public.medicines (category_id);

-- ---------------------------------------------------------------------------
-- Pharmacy list (what a pharmacy says it has; there are NO quantities)
-- ---------------------------------------------------------------------------
create table public.pharmacy_products (
  id uuid primary key default gen_random_uuid(),
  pharmacy_id uuid not null references public.pharmacies (id) on delete restrict,
  medicine_id uuid not null references public.medicines (id) on delete restrict,
  price numeric(14, 2) not null check (price > 0),
  is_available boolean not null default true,
  -- Last time a pharmacist confirmed this price / availability (explicit edit, request answer or bulk confirm).
  confirmed_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint pharmacy_products_unique unique (pharmacy_id, medicine_id)
);
create index pharmacy_products_pharmacy_idx on public.pharmacy_products (pharmacy_id, is_available);
create index pharmacy_products_medicine_idx on public.pharmacy_products (medicine_id, confirmed_at desc)
  where is_available;

-- ---------------------------------------------------------------------------
-- Orders and reservations
-- ---------------------------------------------------------------------------
create table public.orders (
  id uuid primary key default gen_random_uuid(),
  public_ref text not null unique,
  customer_id uuid not null references public.profiles (id) on delete restrict,
  pharmacy_id uuid not null references public.pharmacies (id) on delete restrict,
  status public.order_status not null default 'pending',
  currency text not null check (currency in ('SYP', 'USD')),
  subtotal numeric(14, 2) not null check (subtotal >= 0),
  -- Snapshot of the pharmacy at order time: customers cannot read `pharmacies`, and the order must stay
  -- understandable (where to go, whom to call) even if the pharmacy is suspended or renamed later.
  pharmacy_name text not null default '',
  pharmacy_address text,
  pharmacy_phone text,
  customer_name text not null default '' check (char_length(customer_name) <= 80),
  contact_phone text check (contact_phone is null or contact_phone ~ '^\+?[0-9]{7,15}$'),
  customer_notes text check (customer_notes is null or char_length(customer_notes) <= 300),
  reject_reason text check (reject_reason is null or char_length(reject_reason) <= 300),
  cancel_reason text check (cancel_reason is null or char_length(cancel_reason) <= 300),
  cancelled_by_role text check (cancelled_by_role is null or cancelled_by_role in ('customer', 'pharmacy')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  accepted_at timestamptz,
  ready_at timestamptz,
  completed_at timestamptz,
  rejected_at timestamptz,
  cancelled_at timestamptz,
  expired_at timestamptz,
  reservation_expires_at timestamptz,
  constraint orders_reject_reason_required check (status <> 'rejected' or coalesce(btrim(reject_reason), '') <> '')
);
create index orders_customer_idx on public.orders (customer_id, created_at desc);
create index orders_pharmacy_status_idx on public.orders (pharmacy_id, status, created_at desc);
create index orders_expiry_idx on public.orders (status, reservation_expires_at)
  where status in ('accepted', 'ready_for_pickup');

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  line_no integer not null,
  product_id uuid not null references public.pharmacy_products (id) on delete restrict,
  medicine_id uuid not null references public.medicines (id) on delete restrict,
  medicine_name text not null,
  strength text,
  dosage_form text,
  quantity integer not null check (quantity > 0),
  unit_price numeric(14, 2) not null check (unit_price >= 0),
  line_total numeric(14, 2) generated always as (quantity * unit_price) stored,
  constraint order_items_unique_product unique (order_id, product_id)
);
create index order_items_product_idx on public.order_items (product_id);

-- ---------------------------------------------------------------------------
-- Sales (immutable)
-- ---------------------------------------------------------------------------
create table public.pharmacy_invoice_counters (
  pharmacy_id uuid primary key references public.pharmacies (id) on delete restrict,
  last_number integer not null default 0
);

create table public.sales (
  id uuid primary key default gen_random_uuid(),
  pharmacy_id uuid not null references public.pharmacies (id) on delete restrict,
  invoice_no text not null,
  order_id uuid unique references public.orders (id) on delete restrict,
  payment_method public.payment_method not null default 'cash',
  currency text not null check (currency in ('SYP', 'USD')),
  subtotal numeric(14, 2) not null check (subtotal >= 0),
  discount_amount numeric(14, 2) not null default 0 check (discount_amount >= 0),
  total numeric(14, 2) not null check (total >= 0),
  cashier_id uuid not null references public.profiles (id) on delete restrict,
  created_at timestamptz not null default now(),
  constraint sales_invoice_unique unique (pharmacy_id, invoice_no),
  constraint sales_total_consistent check (total = subtotal - discount_amount),
  constraint sales_discount_le_subtotal check (discount_amount <= subtotal)
);
create index sales_pharmacy_created_idx on public.sales (pharmacy_id, created_at desc);
create index sales_cashier_idx on public.sales (cashier_id);

create table public.sale_items (
  id uuid primary key default gen_random_uuid(),
  sale_id uuid not null references public.sales (id) on delete restrict,
  line_no integer not null,
  product_id uuid not null references public.pharmacy_products (id) on delete restrict,
  product_name text not null,
  strength text,
  quantity integer not null check (quantity > 0),
  unit_price numeric(14, 2) not null check (unit_price >= 0),
  line_total numeric(14, 2) generated always as (quantity * unit_price) stored
);
create index sale_items_sale_idx on public.sale_items (sale_id);
create index sale_items_product_idx on public.sale_items (product_id);

-- ---------------------------------------------------------------------------
-- Availability requests ("is this medicine available near me?"), see docs/availability_design.md
-- Clients have NO access to these tables; everything goes through the RPC functions.
-- ---------------------------------------------------------------------------
create table public.availability_requests (
  id uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.profiles (id) on delete cascade,
  medicine_id uuid not null references public.medicines (id) on delete restrict,
  -- The customer's position, rounded to 3 decimals (~100 m) by the RPC. Never shown to pharmacies.
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  step integer not null default 1 check (step between 1 and 4),
  status public.request_status not null default 'open',
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  last_expanded_at timestamptz not null default now(),
  closed_at timestamptz
);
create index availability_requests_customer_idx on public.availability_requests (customer_id, created_at desc);
create index availability_requests_open_idx on public.availability_requests (expires_at) where status = 'open';

-- One row per (request, notified pharmacy); the pharmacy's answer is stored on the same row.
create table public.availability_targets (
  request_id uuid not null references public.availability_requests (id) on delete cascade,
  pharmacy_id uuid not null references public.pharmacies (id) on delete cascade,
  step integer not null check (step between 1 and 4),
  distance_km numeric(7, 2) not null check (distance_km >= 0),
  notified_at timestamptz not null default now(),
  answer public.request_answer,
  price numeric(14, 2) check (price is null or price > 0),
  answered_by uuid references public.profiles (id) on delete set null,
  answered_at timestamptz,
  primary key (request_id, pharmacy_id),
  constraint availability_targets_answer_shape check (
    (answer is null and price is null and answered_at is null)
    or (answer = 'available' and price is not null and answered_at is not null)
    or (answer = 'unavailable' and price is null and answered_at is not null)
  )
);
create index availability_targets_pharmacy_idx on public.availability_targets (pharmacy_id, notified_at desc);

-- ---------------------------------------------------------------------------
-- Platform
-- ---------------------------------------------------------------------------
create table public.audit_logs (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references public.profiles (id) on delete set null,
  action text not null,
  entity_type text not null,
  entity_id uuid,
  pharmacy_id uuid references public.pharmacies (id) on delete set null,
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index audit_logs_created_idx on public.audit_logs (created_at desc);
create index audit_logs_entity_idx on public.audit_logs (entity_type, entity_id);

create table public.user_reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  target_type public.report_target not null,
  target_id uuid,
  category text not null check (char_length(btrim(category)) between 2 and 60),
  description text not null check (char_length(btrim(description)) between 5 and 1000),
  status public.report_status not null default 'open',
  resolution_note text check (resolution_note is null or char_length(resolution_note) <= 500),
  resolved_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index user_reports_status_idx on public.user_reports (status, created_at desc);
create index user_reports_reporter_idx on public.user_reports (reporter_id);

create table public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null,
  entity_type text,
  entity_id uuid,
  params jsonb not null default '{}'::jsonb,
  read_at timestamptz,
  created_at timestamptz not null default now()
);
create index notifications_user_idx on public.notifications (user_id, created_at desc);

create table public.idempotency_keys (
  user_id uuid not null references public.profiles (id) on delete cascade,
  scope text not null,
  key text not null,
  request_hash text not null,
  response jsonb,
  created_at timestamptz not null default now(),
  primary key (user_id, scope, key)
);
create index idempotency_keys_created_idx on public.idempotency_keys (created_at);

-- ====================================================================================================
-- PART 20261011000003_helpers_and_triggers.sql
-- ====================================================================================================
-- Table-dependent helpers (authorization, audit, notifications, idempotency) and triggers.

-- ---------------------------------------------------------------------------
-- Authorization helpers
-- ---------------------------------------------------------------------------
create function private.is_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.profiles p
    where p.id = (select auth.uid()) and p.role = 'admin' and p.account_status = 'active'
  )
$$;

-- Active membership of the calling user (optionally restricted to roles). Used by RLS policies.
create function private.is_member(p_pharmacy uuid, p_roles public.member_role[] default null) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from public.pharmacy_members m
    join public.profiles p on p.id = m.user_id
    where m.pharmacy_id = p_pharmacy
      and m.user_id = (select auth.uid())
      and m.status = 'active'
      and p.account_status = 'active'
      and (p_roles is null or m.role = any (p_roles))
  )
$$;

-- Returns the caller's id; fails unless the caller is authenticated and not suspended.
create function private.assert_active_user() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_status public.account_status;
begin
  if v_uid is null then
    perform private.fail('not_authenticated');
  end if;
  select p.account_status into v_status from public.profiles p where p.id = v_uid;
  if not found then
    perform private.fail('not_authenticated');
  end if;
  if v_status <> 'active' then
    perform private.fail('account_suspended');
  end if;
  return v_uid;
end
$$;

create function private.assert_admin() returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid;
begin
  v_uid := private.assert_active_user();
  if not private.is_admin() then
    perform private.fail('forbidden');
  end if;
  return v_uid;
end
$$;

-- Caller must be an active member with one of the roles; optionally the pharmacy must be approved.
create function private.assert_member(
  p_pharmacy uuid, p_roles public.member_role[], p_require_approved boolean default true
) returns public.member_role
language plpgsql stable security definer set search_path = '' as $$
declare
  v_role public.member_role;
  v_status public.approval_status;
begin
  select m.role into v_role
  from public.pharmacy_members m
  where m.pharmacy_id = p_pharmacy and m.user_id = auth.uid() and m.status = 'active';
  if v_role is null or not (v_role = any (p_roles)) then
    perform private.fail('forbidden');
  end if;
  if p_require_approved then
    select ph.approval_status into v_status from public.pharmacies ph where ph.id = p_pharmacy;
    if v_status is distinct from 'approved'::public.approval_status then
      perform private.fail('pharmacy_not_active');
    end if;
  end if;
  return v_role;
end
$$;

-- ---------------------------------------------------------------------------
-- Audit, notifications, idempotency
-- ---------------------------------------------------------------------------
create function private.audit(
  p_action text, p_entity_type text, p_entity_id uuid, p_pharmacy_id uuid, p_details jsonb default '{}'::jsonb
) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, pharmacy_id, details)
  values (auth.uid(), p_action, p_entity_type, p_entity_id, p_pharmacy_id, coalesce(p_details, '{}'::jsonb));
end
$$;

create function private.notify(
  p_user uuid, p_kind text, p_entity_type text, p_entity_id uuid, p_params jsonb default '{}'::jsonb
) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.notifications (user_id, kind, entity_type, entity_id, params)
  values (p_user, p_kind, p_entity_type, p_entity_id, coalesce(p_params, '{}'::jsonb));
end
$$;

create function private.notify_pharmacy(
  p_pharmacy uuid, p_kind text, p_entity_type text, p_entity_id uuid, p_params jsonb default '{}'::jsonb
) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.notifications (user_id, kind, entity_type, entity_id, params)
  select m.user_id, p_kind, p_entity_type, p_entity_id, coalesce(p_params, '{}'::jsonb)
  from public.pharmacy_members m
  where m.pharmacy_id = p_pharmacy and m.status = 'active';
end
$$;

-- Returns the stored response for an already-processed (user, scope, key), or NULL when this is
-- the first time. The key row is created inside the caller's transaction, so concurrent duplicates
-- serialise on the primary key and a failed attempt leaves no trace.
create function private.idem_begin(p_user uuid, p_scope text, p_key text, p_hash text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_inserted integer;
  v_hash text;
  v_response jsonb;
begin
  if p_key is null or char_length(p_key) < 8 or char_length(p_key) > 100 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'idempotency_key'));
  end if;
  insert into public.idempotency_keys (user_id, scope, key, request_hash)
  values (p_user, p_scope, p_key, p_hash)
  on conflict do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 1 then
    return null;
  end if;
  select k.request_hash, k.response into v_hash, v_response
  from public.idempotency_keys k
  where k.user_id = p_user and k.scope = p_scope and k.key = p_key;
  if v_hash is distinct from p_hash then
    perform private.fail('duplicate_request', jsonb_build_object('reason', 'key_reused_with_different_request'));
  end if;
  return v_response;
end
$$;

create function private.idem_finish(p_user uuid, p_scope text, p_key text, p_response jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  update public.idempotency_keys
  set response = p_response
  where user_id = p_user and scope = p_scope and key = p_key;
end
$$;

-- Parses [{product_id, quantity, expected_unit_price?}] into merged, validated rows.
create function private.parse_items(p_items jsonb, p_max_lines integer, p_max_qty integer)
returns table (product_id uuid, quantity integer, expected_unit_price numeric)
language plpgsql stable set search_path = '' as $$
begin
  -- Nested checks: never rely on the evaluation order of OR operands.
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;
  if jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > p_max_lines then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;
  if exists (select 1 from jsonb_array_elements(p_items) e where jsonb_typeof(e) <> 'object') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as x (product_id uuid, quantity integer, expected_unit_price numeric)
    where x.product_id is null or x.quantity is null or x.quantity < 1
       or coalesce(x.expected_unit_price, 0) < 0
  ) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_items) as x (product_id uuid, quantity integer, expected_unit_price numeric)
    group by x.product_id
    having sum(x.quantity) > p_max_qty
  ) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'quantity', 'max', p_max_qty));
  end if;

  return query
    select x.product_id, sum(x.quantity)::integer, max(x.expected_unit_price)
    from jsonb_to_recordset(p_items) as x (product_id uuid, quantity integer, expected_unit_price numeric)
    group by x.product_id
    order by x.product_id;
exception
  when invalid_text_representation or numeric_value_out_of_range or datatype_mismatch or invalid_parameter_value then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
end
$$;

-- ---------------------------------------------------------------------------
-- Generic triggers
-- ---------------------------------------------------------------------------
create function private.set_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end
$$;

create trigger profiles_set_updated_at before update on public.profiles
  for each row execute function private.set_updated_at();
create trigger pharmacies_set_updated_at before update on public.pharmacies
  for each row execute function private.set_updated_at();
create trigger medicines_set_updated_at before update on public.medicines
  for each row execute function private.set_updated_at();
create trigger pharmacy_products_set_updated_at before update on public.pharmacy_products
  for each row execute function private.set_updated_at();
create trigger orders_set_updated_at before update on public.orders
  for each row execute function private.set_updated_at();
create trigger user_reports_set_updated_at before update on public.user_reports
  for each row execute function private.set_updated_at();

-- Append-only tables: history can never be edited or removed.
create function private.reject_mutation() returns trigger
language plpgsql as $$
begin
  raise exception using errcode = 'P0001', message = 'append_only', detail = tg_table_name;
end
$$;

create trigger sales_append_only before update or delete on public.sales
  for each row execute function private.reject_mutation();
create trigger sale_items_append_only before update or delete on public.sale_items
  for each row execute function private.reject_mutation();
create trigger audit_logs_append_only before update or delete on public.audit_logs
  for each row execute function private.reject_mutation();

create trigger sales_no_truncate before truncate on public.sales
  for each statement execute function private.reject_mutation();
create trigger sale_items_no_truncate before truncate on public.sale_items
  for each statement execute function private.reject_mutation();
create trigger audit_logs_no_truncate before truncate on public.audit_logs
  for each statement execute function private.reject_mutation();

-- ---------------------------------------------------------------------------
-- Profiles
-- ---------------------------------------------------------------------------
-- Every auth user gets a CUSTOMER profile. Client-supplied metadata can never choose the role.
create function private.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, display_name, phone)
  values (
    new.id,
    left(btrim(coalesce(new.raw_user_meta_data ->> 'display_name', '')), 80),
    private.clean_phone(new.raw_user_meta_data ->> 'phone')
  )
  on conflict (id) do nothing;
  return new;
end
$$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function private.handle_new_user();

-- Defence in depth: client roles can never change privileged profile columns.
create function private.profiles_guard() returns trigger
language plpgsql as $$
begin
  if current_user in ('anon', 'authenticated') then
    if new.id is distinct from old.id
       or new.role is distinct from old.role
       or new.account_status is distinct from old.account_status
       or new.suspended_reason is distinct from old.suspended_reason then
      raise exception using errcode = '42501', message = 'forbidden';
    end if;
  end if;
  return new;
end
$$;

create trigger profiles_guard_trg before update on public.profiles
  for each row execute function private.profiles_guard();

-- ---------------------------------------------------------------------------
-- Pharmacies
-- ---------------------------------------------------------------------------
create function private.pharmacies_guard() returns trigger
language plpgsql as $$
begin
  if current_user in ('anon', 'authenticated') then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;
  if new.owner_id is distinct from old.owner_id then
    perform private.fail('forbidden', jsonb_build_object('field', 'owner_id'));
  end if;
  if old.approval_status in ('approved', 'suspended') and new.currency is distinct from old.currency then
    perform private.fail('invalid_input', jsonb_build_object('field', 'currency', 'reason', 'immutable_after_approval'));
  end if;
  return new;
end
$$;

create trigger pharmacies_guard_trg before update on public.pharmacies
  for each row execute function private.pharmacies_guard();

-- Pharmacy products: identity columns are immutable.
create function private.pharmacy_products_guard() returns trigger
language plpgsql as $$
begin
  if new.pharmacy_id is distinct from old.pharmacy_id or new.medicine_id is distinct from old.medicine_id then
    perform private.fail('forbidden', jsonb_build_object('field', 'identity'));
  end if;
  return new;
end
$$;

create trigger pharmacy_products_guard_trg before update on public.pharmacy_products
  for each row execute function private.pharmacy_products_guard();

-- ---------------------------------------------------------------------------
-- Orders: explicit state machine + immutable identity/amount columns.
-- ---------------------------------------------------------------------------
create function private.orders_guard() returns trigger
language plpgsql as $$
begin
  if new.customer_id is distinct from old.customer_id
     or new.pharmacy_id is distinct from old.pharmacy_id
     or new.public_ref is distinct from old.public_ref
     or new.currency is distinct from old.currency
     or new.subtotal is distinct from old.subtotal then
    perform private.fail('forbidden', jsonb_build_object('field', 'order_identity'));
  end if;

  if old.status in ('completed', 'rejected', 'cancelled') then
    perform private.fail('invalid_transition', jsonb_build_object('from', old.status, 'to', new.status));
  end if;

  if new.status is distinct from old.status
     and not private.order_transition_allowed(old.status, new.status) then
    perform private.fail('invalid_transition', jsonb_build_object('from', old.status, 'to', new.status));
  end if;
  return new;
end
$$;

create trigger orders_guard_trg before update on public.orders
  for each row execute function private.orders_guard();

-- ---------------------------------------------------------------------------
-- Catalogue changes made directly by admins are audited.
-- ---------------------------------------------------------------------------
create function private.audit_catalog_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.audit_logs (actor_id, action, entity_type, entity_id, details)
  values (
    auth.uid(),
    lower(tg_op) || '_' || tg_table_name,
    tg_table_name,
    case when tg_op = 'DELETE' then old.id else new.id end,
    jsonb_build_object('op', tg_op)
  );
  return coalesce(new, old);
end
$$;

create trigger medicines_audit after insert or update on public.medicines
  for each row execute function private.audit_catalog_change();
create trigger medicine_categories_audit after insert or update on public.medicine_categories
  for each row execute function private.audit_catalog_change();

-- ====================================================================================================
-- PART 20261011000004_rls_and_grants.sql
-- ====================================================================================================
-- Row Level Security, grants and policies.
-- Strategy: deny everything, then grant the minimum. Writes with business meaning go through
-- SECURITY DEFINER functions (later migrations); tables without a write policy are read-only to clients.

-- ---------------------------------------------------------------------------
-- 1. Override Supabase's permissive default grants
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from public, anon, authenticated;

alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke execute on functions from anon, authenticated;
alter default privileges in schema private revoke execute on functions from anon, authenticated;

-- private schema: usable (for policy helpers) but not exposed through the API.
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
revoke execute on all functions in schema private from public, anon, authenticated;
grant execute on function private.is_admin() to authenticated;
grant execute on function private.is_member(uuid, public.member_role[]) to authenticated;
grant execute on function private.normalize_search(text) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. Enable RLS on every table
-- ---------------------------------------------------------------------------
alter table public.profiles enable row level security;
alter table public.pharmacies enable row level security;
alter table public.pharmacy_members enable row level security;
alter table public.medicine_categories enable row level security;
alter table public.medicines enable row level security;
alter table public.pharmacy_products enable row level security;
alter table public.orders enable row level security;
alter table public.order_items enable row level security;
alter table public.sales enable row level security;
alter table public.sale_items enable row level security;
alter table public.audit_logs enable row level security;
alter table public.user_reports enable row level security;
alter table public.notifications enable row level security;
alter table public.idempotency_keys enable row level security;
alter table public.pharmacy_invoice_counters enable row level security;
alter table public.availability_requests enable row level security;
alter table public.availability_targets enable row level security;

-- ---------------------------------------------------------------------------
-- 3. Grants (SELECT only unless stated). Policies below decide which rows.
-- ---------------------------------------------------------------------------
grant select on
  public.profiles, public.pharmacies, public.pharmacy_members, public.medicine_categories,
  public.medicines, public.pharmacy_products, public.orders,
  public.order_items, public.sales, public.sale_items,
  public.audit_logs, public.user_reports, public.notifications
to authenticated;

-- Profiles: users may edit only these columns of their own row.
grant update (display_name, phone, locale) on public.profiles to authenticated;

-- Reports: users may file reports (reporter_id/status are server-controlled).
grant insert (target_type, target_id, category, description) on public.user_reports to authenticated;

-- Notifications: users may mark their own as read.
grant update (read_at) on public.notifications to authenticated;

-- Catalogue: admin-only writes (enforced by policy; non-admins fail RLS).
grant insert (name_ar, name_en, sort_order, is_active) on public.medicine_categories to authenticated;
grant update (name_ar, name_en, sort_order, is_active) on public.medicine_categories to authenticated;
grant insert (category_id, name_ar, name_en, brand_name, active_ingredient, strength, dosage_form,
              package_description, catalog_status) on public.medicines to authenticated;
grant update (category_id, name_ar, name_en, brand_name, active_ingredient, strength, dosage_form,
              package_description, catalog_status) on public.medicines to authenticated;

-- Everything else (pharmacies, products, orders, sales, ...) has NO client write grant.
-- idempotency_keys, pharmacy_invoice_counters, availability_requests, availability_targets: no client access at all.

-- ---------------------------------------------------------------------------
-- 4. Policies
-- ---------------------------------------------------------------------------
-- profiles
create policy profiles_select_own on public.profiles
  for select to authenticated using (id = (select auth.uid()));
create policy profiles_select_admin on public.profiles
  for select to authenticated using (private.is_admin() and role <> 'customer');
create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = (select auth.uid())) with check (id = (select auth.uid()));

-- pharmacies: members, owner and admin only. Customers use the public RPCs (masked data).
create policy pharmacies_select on public.pharmacies
  for select to authenticated
  using (owner_id = (select auth.uid()) or private.is_member(id) or private.is_admin());

-- pharmacy_members
create policy pharmacy_members_select_own on public.pharmacy_members
  for select to authenticated using (user_id = (select auth.uid()));
create policy pharmacy_members_select_owner on public.pharmacy_members
  for select to authenticated
  using (private.is_member(pharmacy_id, array['owner']::public.member_role[]));
create policy pharmacy_members_select_admin on public.pharmacy_members
  for select to authenticated using (private.is_admin());

-- medicine_categories
create policy medicine_categories_select on public.medicine_categories
  for select to authenticated using (is_active or private.is_admin());
create policy medicine_categories_insert_admin on public.medicine_categories
  for insert to authenticated with check (private.is_admin());
create policy medicine_categories_update_admin on public.medicine_categories
  for update to authenticated using (private.is_admin()) with check (private.is_admin());

-- medicines
create policy medicines_select on public.medicines
  for select to authenticated
  using (catalog_status = 'approved' or proposed_by = (select auth.uid()) or private.is_admin());
create policy medicines_insert_admin on public.medicines
  for insert to authenticated with check (private.is_admin());
create policy medicines_update_admin on public.medicines
  for update to authenticated using (private.is_admin()) with check (private.is_admin());

-- pharmacy_products: active members of that pharmacy.
create policy pharmacy_products_select on public.pharmacy_products
  for select to authenticated using (private.is_member(pharmacy_id));

-- orders: the customer, or members of the order's pharmacy. Admins get nothing (privacy).
create policy orders_select on public.orders
  for select to authenticated
  using (customer_id = (select auth.uid()) or private.is_member(pharmacy_id));

-- order_items inherit order visibility (the subquery is itself subject to orders RLS).
create policy order_items_select on public.order_items
  for select to authenticated
  using (exists (select 1 from public.orders o where o.id = order_id));

-- sales: owner/manager see all, cashier sees own sales.
create policy sales_select on public.sales
  for select to authenticated
  using (
    private.is_member(pharmacy_id, array['owner', 'manager']::public.member_role[])
    or (cashier_id = (select auth.uid()) and private.is_member(pharmacy_id))
  );
create policy sale_items_select on public.sale_items
  for select to authenticated
  using (exists (select 1 from public.sales s where s.id = sale_id));

-- audit_logs: admin only.
create policy audit_logs_select_admin on public.audit_logs
  for select to authenticated using (private.is_admin());

-- user_reports
create policy user_reports_insert_own on public.user_reports
  for insert to authenticated with check (reporter_id = (select auth.uid()));
create policy user_reports_select_own on public.user_reports
  for select to authenticated using (reporter_id = (select auth.uid()));
create policy user_reports_select_admin on public.user_reports
  for select to authenticated using (private.is_admin());

-- notifications
create policy notifications_select_own on public.notifications
  for select to authenticated using (user_id = (select auth.uid()));
create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- idempotency_keys / pharmacy_invoice_counters / availability_requests / availability_targets:
-- RLS on, no policies, no grants => unreachable by clients (RPC functions only).

-- ====================================================================================================
-- PART 20261011000005_rpc_accounts_admin_listing.sql
-- ====================================================================================================
-- Trusted functions: pharmacy onboarding, admin actions, catalogue proposals, the pharmacy list (no quantities).
-- All are SECURITY DEFINER with an empty search_path and re-derive the caller from auth.uid().

-- ---------------------------------------------------------------------------
-- Pharmacy onboarding
-- ---------------------------------------------------------------------------
create function public.register_pharmacy(
  p_name text,
  p_phone text,
  p_address_line text,
  p_neighborhood text,
  p_city text,
  p_directions text,
  p_opening_hours jsonb,
  p_currency text,
  p_license_path text,
  p_latitude double precision,
  p_longitude double precision,
  p_show_phone_publicly boolean default true
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_role public.user_role;
  v_phone text;
  v_license text;
  v_hours jsonb := coalesce(p_opening_hours, '{}'::jsonb);
  v_pharmacy public.pharmacies;
begin
  v_uid := private.assert_active_user();
  select p.role into v_role from public.profiles p where p.id = v_uid;
  if v_role = 'admin' then
    perform private.fail('forbidden');
  end if;
  if exists (select 1 from public.pharmacies ph where ph.owner_id = v_uid) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'pharmacy', 'reason', 'already_registered'));
  end if;

  v_phone := private.clean_phone(p_phone);
  if v_phone is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'phone'));
  end if;
  if coalesce(p_currency, 'SYP') not in ('SYP', 'USD') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'currency'));
  end if;
  if jsonb_typeof(v_hours) <> 'object' or char_length(v_hours::text) > 2000 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'opening_hours'));
  end if;
  v_license := btrim(coalesce(p_license_path, ''));
  if v_license = '' or v_license not like v_uid::text || '/%' or v_license like '%..%' or char_length(v_license) > 300 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'license_document'));
  end if;
  perform private.check_location(p_latitude, p_longitude);

  insert into public.pharmacies (
    owner_id, name, phone, show_phone_publicly, address_line, neighborhood, city, directions,
    opening_hours, currency, license_document_path, latitude, longitude
  ) values (
    v_uid,
    private.req_text(p_name, 'name', 2, 120),
    v_phone,
    coalesce(p_show_phone_publicly, true),
    private.req_text(p_address_line, 'address_line', 3, 250),
    coalesce(private.req_text(p_neighborhood, 'neighborhood', 1, 100, false), ''),
    private.req_text(p_city, 'city', 2, 100),
    private.req_text(p_directions, 'directions', 1, 500, false),
    v_hours,
    coalesce(p_currency, 'SYP'),
    v_license,
    p_latitude,
    p_longitude
  ) returning * into v_pharmacy;

  insert into public.pharmacy_members (pharmacy_id, user_id, role, status)
  values (v_pharmacy.id, v_uid, 'owner', 'active');

  update public.profiles set role = 'pharmacist' where id = v_uid and role = 'customer';

  perform private.audit('pharmacy_registered', 'pharmacy', v_pharmacy.id, v_pharmacy.id, '{}'::jsonb);
  return to_jsonb(v_pharmacy);
end
$$;

-- Owner re-submits a rejected application (optionally with a new licence document).
create function public.resubmit_pharmacy(
  p_pharmacy_id uuid,
  p_name text,
  p_phone text,
  p_address_line text,
  p_neighborhood text,
  p_city text,
  p_directions text,
  p_opening_hours jsonb,
  p_license_path text default null,
  p_show_phone_publicly boolean default true,
  p_latitude double precision default null,
  p_longitude double precision default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_ph public.pharmacies;
  v_phone text;
  v_license text;
  v_hours jsonb := coalesce(p_opening_hours, '{}'::jsonb);
begin
  v_uid := private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner']::public.member_role[], false);
  select * into v_ph from public.pharmacies where id = p_pharmacy_id for update;
  if v_ph.approval_status <> 'rejected' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_ph.approval_status, 'to', 'pending'));
  end if;

  v_phone := private.clean_phone(p_phone);
  if v_phone is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'phone'));
  end if;
  if jsonb_typeof(v_hours) <> 'object' or char_length(v_hours::text) > 2000 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'opening_hours'));
  end if;
  v_license := nullif(btrim(coalesce(p_license_path, '')), '');
  if v_license is not null and (v_license not like v_uid::text || '/%' or v_license like '%..%' or char_length(v_license) > 300) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'license_document'));
  end if;
  -- NULL coordinates keep the current location; when either is given both must be valid.
  if p_latitude is not null or p_longitude is not null then
    perform private.check_location(p_latitude, p_longitude);
  end if;

  update public.pharmacies set
    name = private.req_text(p_name, 'name', 2, 120),
    phone = v_phone,
    show_phone_publicly = coalesce(p_show_phone_publicly, true),
    address_line = private.req_text(p_address_line, 'address_line', 3, 250),
    neighborhood = coalesce(private.req_text(p_neighborhood, 'neighborhood', 1, 100, false), ''),
    city = private.req_text(p_city, 'city', 2, 100),
    directions = private.req_text(p_directions, 'directions', 1, 500, false),
    opening_hours = v_hours,
    license_document_path = coalesce(v_license, license_document_path),
    latitude = coalesce(p_latitude, latitude),
    longitude = coalesce(p_longitude, longitude),
    approval_status = 'pending',
    status_reason = null,
    reviewed_by = null,
    reviewed_at = null,
    is_listed = false,
    submitted_at = now()
  where id = p_pharmacy_id
  returning * into v_ph;

  perform private.audit('pharmacy_resubmitted', 'pharmacy', v_ph.id, v_ph.id, '{}'::jsonb);
  return to_jsonb(v_ph);
end
$$;

-- Owner edits an approved pharmacy. NULL parameters mean "leave unchanged".
create function public.update_my_pharmacy(
  p_pharmacy_id uuid,
  p_name text default null,
  p_phone text default null,
  p_address_line text default null,
  p_neighborhood text default null,
  p_city text default null,
  p_directions text default null,
  p_opening_hours jsonb default null,
  p_show_phone_publicly boolean default null,
  p_is_listed boolean default null,
  p_latitude double precision default null,
  p_longitude double precision default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_ph public.pharmacies;
  v_phone text;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner']::public.member_role[], true);
  select * into v_ph from public.pharmacies where id = p_pharmacy_id for update;

  if p_phone is not null then
    v_phone := private.clean_phone(p_phone);
    if v_phone is null then
      perform private.fail('invalid_input', jsonb_build_object('field', 'phone'));
    end if;
  end if;
  if p_opening_hours is not null
     and (jsonb_typeof(p_opening_hours) <> 'object' or char_length(p_opening_hours::text) > 2000) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'opening_hours'));
  end if;
  -- NULL coordinates keep the current location; when either is given both must be valid.
  if p_latitude is not null or p_longitude is not null then
    perform private.check_location(p_latitude, p_longitude);
  end if;

  update public.pharmacies set
    name = coalesce(private.req_text(p_name, 'name', 2, 120, false), name),
    phone = coalesce(v_phone, phone),
    address_line = coalesce(private.req_text(p_address_line, 'address_line', 3, 250, false), address_line),
    neighborhood = coalesce(private.req_text(p_neighborhood, 'neighborhood', 1, 100, false), neighborhood),
    city = coalesce(private.req_text(p_city, 'city', 2, 100, false), city),
    directions = coalesce(private.req_text(p_directions, 'directions', 1, 500, false), directions),
    opening_hours = coalesce(p_opening_hours, opening_hours),
    show_phone_publicly = coalesce(p_show_phone_publicly, show_phone_publicly),
    is_listed = coalesce(p_is_listed, is_listed),
    latitude = coalesce(p_latitude, latitude),
    longitude = coalesce(p_longitude, longitude)
  where id = p_pharmacy_id
  returning * into v_ph;

  perform private.audit('pharmacy_updated', 'pharmacy', v_ph.id, v_ph.id,
                        jsonb_build_object('location_changed', p_latitude is not null));
  return to_jsonb(v_ph);
end
$$;

-- ---------------------------------------------------------------------------
-- Admin
-- ---------------------------------------------------------------------------
create function public.admin_review_pharmacy(p_pharmacy_id uuid, p_decision text, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_ph public.pharmacies;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_new public.approval_status;
  v_kind text;
begin
  v_uid := private.assert_admin();
  select * into v_ph from public.pharmacies where id = p_pharmacy_id for update;
  if not found then
    perform private.fail('not_found');
  end if;

  case p_decision
    when 'approve' then
      if v_ph.approval_status <> 'pending' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_ph.approval_status, 'to', 'approved'));
      end if;
      v_new := 'approved'; v_kind := 'pharmacy_approved';
    when 'reject' then
      if v_ph.approval_status <> 'pending' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_ph.approval_status, 'to', 'rejected'));
      end if;
      if v_reason is null then
        perform private.fail('invalid_input', jsonb_build_object('field', 'reason', 'reason', 'required'));
      end if;
      v_new := 'rejected'; v_kind := 'pharmacy_rejected';
    when 'suspend' then
      if v_ph.approval_status <> 'approved' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_ph.approval_status, 'to', 'suspended'));
      end if;
      if v_reason is null then
        perform private.fail('invalid_input', jsonb_build_object('field', 'reason', 'reason', 'required'));
      end if;
      v_new := 'suspended'; v_kind := 'pharmacy_suspended';
    when 'reinstate' then
      if v_ph.approval_status <> 'suspended' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_ph.approval_status, 'to', 'approved'));
      end if;
      v_new := 'approved'; v_kind := 'pharmacy_reinstated';
    else
      perform private.fail('invalid_input', jsonb_build_object('field', 'decision'));
  end case;

  update public.pharmacies set
    approval_status = v_new,
    status_reason = case when v_new in ('rejected', 'suspended') then v_reason else null end,
    is_listed = (v_new = 'approved'),
    reviewed_by = v_uid,
    reviewed_at = now()
  where id = p_pharmacy_id
  returning * into v_ph;

  perform private.audit('pharmacy_' || p_decision, 'pharmacy', v_ph.id, v_ph.id,
                        jsonb_build_object('reason', v_reason, 'status', v_new));
  perform private.notify(v_ph.owner_id, v_kind, 'pharmacy', v_ph.id, jsonb_build_object('reason', v_reason));
  return to_jsonb(v_ph);
end
$$;

create function public.admin_set_account_status(p_user_id uuid, p_status text, p_reason text default null)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_target public.profiles;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  v_uid := private.assert_admin();
  if p_user_id = v_uid then
    perform private.fail('forbidden', jsonb_build_object('reason', 'self'));
  end if;
  if p_status not in ('active', 'suspended') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'status'));
  end if;
  if p_status = 'suspended' and v_reason is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'reason', 'reason', 'required'));
  end if;
  select * into v_target from public.profiles where id = p_user_id for update;
  if not found then
    perform private.fail('not_found');
  end if;
  if v_target.role = 'admin' then
    perform private.fail('forbidden', jsonb_build_object('reason', 'target_is_admin'));
  end if;

  update public.profiles set
    account_status = p_status::public.account_status,
    suspended_reason = case when p_status = 'suspended' then v_reason else null end
  where id = p_user_id;

  perform private.audit('account_' || p_status, 'profile', p_user_id, null, jsonb_build_object('reason', v_reason));
  return jsonb_build_object('id', p_user_id, 'account_status', p_status);
end
$$;

create function public.admin_review_medicine(p_medicine_id uuid, p_decision text)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_med public.medicines;
  v_new public.catalog_status;
begin
  v_uid := private.assert_admin();
  select * into v_med from public.medicines where id = p_medicine_id for update;
  if not found then
    perform private.fail('not_found');
  end if;
  case p_decision
    when 'approve' then
      if v_med.catalog_status <> 'pending' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_med.catalog_status, 'to', 'approved'));
      end if;
      v_new := 'approved';
    when 'reject' then
      if v_med.catalog_status <> 'pending' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_med.catalog_status, 'to', 'rejected'));
      end if;
      v_new := 'rejected';
    when 'archive' then
      if v_med.catalog_status = 'archived' then
        perform private.fail('invalid_transition', jsonb_build_object('from', v_med.catalog_status, 'to', 'archived'));
      end if;
      v_new := 'archived';
    else
      perform private.fail('invalid_input', jsonb_build_object('field', 'decision'));
  end case;
  update public.medicines set catalog_status = v_new, reviewed_by = v_uid, reviewed_at = now()
  where id = p_medicine_id;
  perform private.audit('medicine_' || p_decision, 'medicine', p_medicine_id, null, '{}'::jsonb);
  return jsonb_build_object('id', p_medicine_id, 'catalog_status', v_new);
end
$$;

create function public.admin_resolve_report(p_report_id uuid, p_status text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v_uid := private.assert_admin();
  if p_status not in ('in_review', 'resolved', 'dismissed') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'status'));
  end if;
  if char_length(coalesce(v_note, '')) > 500 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'note'));
  end if;
  update public.user_reports set
    status = p_status::public.report_status,
    resolution_note = v_note,
    resolved_by = v_uid
  where id = p_report_id;
  if not found then
    perform private.fail('not_found');
  end if;
  perform private.audit('report_' || p_status, 'user_report', p_report_id, null, '{}'::jsonb);
  return jsonb_build_object('id', p_report_id, 'status', p_status);
end
$$;

-- Aggregates only: no personal data.
create function public.admin_metrics() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
begin
  perform private.assert_admin();
  return jsonb_build_object(
    'pharmacies', jsonb_build_object(
      'pending', (select count(*) from public.pharmacies where approval_status = 'pending'),
      'approved', (select count(*) from public.pharmacies where approval_status = 'approved'),
      'rejected', (select count(*) from public.pharmacies where approval_status = 'rejected'),
      'suspended', (select count(*) from public.pharmacies where approval_status = 'suspended')
    ),
    'users', jsonb_build_object(
      'customers', (select count(*) from public.profiles where role = 'customer'),
      'pharmacists', (select count(*) from public.profiles where role = 'pharmacist'),
      'suspended', (select count(*) from public.profiles where account_status = 'suspended')
    ),
    'medicines', jsonb_build_object(
      'approved', (select count(*) from public.medicines where catalog_status = 'approved'),
      'pending', (select count(*) from public.medicines where catalog_status = 'pending')
    ),
    'orders_30d', jsonb_build_object(
      'total', (select count(*) from public.orders where created_at >= now() - interval '30 days'),
      'completed', (select count(*) from public.orders where status = 'completed' and created_at >= now() - interval '30 days'),
      'cancelled_or_rejected', (select count(*) from public.orders where status in ('cancelled', 'rejected') and created_at >= now() - interval '30 days')
    ),
    'sales_30d_count', (select count(*) from public.sales where created_at >= now() - interval '30 days'),
    'open_reports', (select count(*) from public.user_reports where status in ('open', 'in_review'))
  );
end
$$;

-- ---------------------------------------------------------------------------
-- Catalogue proposals (pharmacists propose; admin approves)
-- ---------------------------------------------------------------------------
create function public.propose_medicine(
  p_name_ar text,
  p_name_en text,
  p_brand_name text,
  p_active_ingredient text,
  p_strength text,
  p_dosage_form text,
  p_package_description text,
  p_category_id uuid default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_name_ar text := private.req_text(p_name_ar, 'name_ar', 1, 160, false);
  v_name_en text := private.req_text(p_name_en, 'name_en', 1, 160, false);
  v_brand text := private.req_text(p_brand_name, 'brand_name', 1, 160, false);
  v_ingredient text := private.req_text(p_active_ingredient, 'active_ingredient', 1, 200, false);
  v_strength text := private.req_text(p_strength, 'strength', 1, 60, false);
  v_form text := private.req_text(p_dosage_form, 'dosage_form', 1, 60, false);
  v_pack text := private.req_text(p_package_description, 'package_description', 1, 200, false);
  v_key text;
  v_existing public.medicines;
  v_new public.medicines;
begin
  v_uid := private.assert_active_user();
  if not private.is_admin() and not exists (
    select 1
    from public.pharmacy_members m
    join public.pharmacies ph on ph.id = m.pharmacy_id
    where m.user_id = v_uid and m.status = 'active'
      and m.role in ('owner', 'manager') and ph.approval_status = 'approved'
  ) then
    perform private.fail('forbidden');
  end if;
  if v_name_ar is null and v_name_en is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'name'));
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.medicine_categories c where c.id = p_category_id and c.is_active
  ) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'category_id'));
  end if;

  v_key := private.normalize_search(
    coalesce(v_name_ar, '') || '|' || coalesce(v_name_en, '') || '|' || coalesce(v_brand, '') || '|' ||
    coalesce(v_strength, '') || '|' || coalesce(v_form, '') || '|' || coalesce(v_pack, '')
  );

  select * into v_existing
  from public.medicines m
  where m.dedupe_key = v_key and m.catalog_status in ('pending', 'approved');
  if found then
    return jsonb_build_object('id', v_existing.id, 'catalog_status', v_existing.catalog_status, 'existed', true);
  end if;

  begin
    insert into public.medicines (
      category_id, name_ar, name_en, brand_name, active_ingredient, strength, dosage_form,
      package_description, catalog_status, proposed_by
    ) values (
      p_category_id, v_name_ar, v_name_en, v_brand, v_ingredient, v_strength, v_form, v_pack, 'pending', v_uid
    ) returning * into v_new;
  exception when unique_violation then
    select * into v_existing
    from public.medicines m
    where m.dedupe_key = v_key and m.catalog_status in ('pending', 'approved');
    return jsonb_build_object('id', v_existing.id, 'catalog_status', v_existing.catalog_status, 'existed', true);
  end;

  return jsonb_build_object('id', v_new.id, 'catalog_status', v_new.catalog_status, 'existed', false);
end
$$;

-- ---------------------------------------------------------------------------
-- The pharmacy list (what the pharmacy says it has; no quantities, see docs/availability_design.md)
-- ---------------------------------------------------------------------------
create function public.add_pharmacy_product(
  p_pharmacy_id uuid,
  p_medicine_id uuid,
  p_price numeric
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_existing uuid;
  v_product public.pharmacy_products;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager']::public.member_role[], true);
  if p_price is null or p_price <= 0 or p_price > 999999999999 or scale(p_price) > 2 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'price'));
  end if;
  if not exists (select 1 from public.medicines m where m.id = p_medicine_id and m.catalog_status = 'approved') then
    perform private.fail('not_found', jsonb_build_object('field', 'medicine_id'));
  end if;
  select pp.id into v_existing from public.pharmacy_products pp
  where pp.pharmacy_id = p_pharmacy_id and pp.medicine_id = p_medicine_id;
  if v_existing is not null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'medicine_id', 'reason', 'already_exists', 'product_id', v_existing));
  end if;

  insert into public.pharmacy_products (pharmacy_id, medicine_id, price)
  values (p_pharmacy_id, p_medicine_id, p_price)
  returning * into v_product;

  perform private.audit('product_added', 'pharmacy_product', v_product.id, p_pharmacy_id,
                        jsonb_build_object('price', p_price));
  return to_jsonb(v_product);
end
$$;

-- NULL parameters mean "leave unchanged". Any call confirms the row (confirmed_at = now()).
create function public.update_pharmacy_product(
  p_product_id uuid,
  p_price numeric default null,
  p_is_available boolean default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_pharmacy uuid;
  v_old public.pharmacy_products;
  v_new public.pharmacy_products;
begin
  perform private.assert_active_user();
  select pp.pharmacy_id into v_pharmacy from public.pharmacy_products pp where pp.id = p_product_id;
  if v_pharmacy is null then
    perform private.fail('not_found');
  end if;
  perform private.assert_member(v_pharmacy, array['owner', 'manager']::public.member_role[], true);
  if p_price is not null and (p_price <= 0 or p_price > 999999999999 or scale(p_price) > 2) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'price'));
  end if;

  select * into v_old from public.pharmacy_products where id = p_product_id for update;
  update public.pharmacy_products set
    price = coalesce(p_price, price),
    is_available = coalesce(p_is_available, is_available),
    confirmed_at = now()
  where id = p_product_id
  returning * into v_new;

  if v_new.price is distinct from v_old.price or v_new.is_available is distinct from v_old.is_available then
    perform private.audit('product_updated', 'pharmacy_product', p_product_id, v_pharmacy, jsonb_build_object(
      'price', jsonb_build_array(v_old.price, v_new.price),
      'is_available', jsonb_build_array(v_old.is_available, v_new.is_available)
    ));
  end if;
  return to_jsonb(v_new);
end
$$;

-- "My list is still correct today": refreshes the confirmation time of every available product.
create function public.confirm_listing(p_pharmacy_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_count integer;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager']::public.member_role[], true);
  update public.pharmacy_products set confirmed_at = now()
  where pharmacy_id = p_pharmacy_id and is_available;
  get diagnostics v_count = row_count;
  perform private.audit('listing_confirmed', 'pharmacy', p_pharmacy_id, p_pharmacy_id,
                        jsonb_build_object('products', v_count));
  return jsonb_build_object('confirmed', v_count);
end
$$;

-- Bulk import: [{medicine_id, price}] (at most max_import_items). Rows whose medicine is not an approved
-- catalogue entry, or whose price is not a positive amount with <= 2 decimals, are skipped (counted).
-- Existing rows get the new price and become available + confirmed. Duplicates in one call: the last wins.
create function public.bulk_upsert_pharmacy_products(p_pharmacy_id uuid, p_items jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_total integer;
  v_inserted integer;
  v_updated integer;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager']::public.member_role[], true);
  if p_items is null or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > private.cfg_int('max_import_items') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;
  if exists (select 1 from jsonb_array_elements(p_items) e where jsonb_typeof(e) <> 'object') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
  end if;
  v_total := jsonb_array_length(p_items);

  with raw as (
    select x.medicine_id, x.price, x.ord
    from rows from (jsonb_to_recordset(p_items) as (medicine_id uuid, price numeric)) with ordinality as x (medicine_id, price, ord)
  ),
  valid as (
    select distinct on (r.medicine_id) r.medicine_id, r.price
    from raw r
    join public.medicines m on m.id = r.medicine_id and m.catalog_status = 'approved'
    where r.price is not null and r.price > 0 and r.price <= 999999999999 and scale(r.price) <= 2
    order by r.medicine_id, r.ord desc
  ),
  up as (
    insert into public.pharmacy_products as pp (pharmacy_id, medicine_id, price, is_available, confirmed_at)
    select p_pharmacy_id, v.medicine_id, v.price, true, now() from valid v
    on conflict (pharmacy_id, medicine_id) do update
      set price = excluded.price, is_available = true, confirmed_at = now()
    returning (xmax = 0) as was_inserted
  )
  select count(*) filter (where was_inserted), count(*) filter (where not was_inserted)
  into v_inserted, v_updated
  from up;

  perform private.audit('products_imported', 'pharmacy', p_pharmacy_id, p_pharmacy_id,
                        jsonb_build_object('inserted', v_inserted, 'updated', v_updated,
                                           'skipped', v_total - v_inserted - v_updated));
  return jsonb_build_object('inserted', v_inserted, 'updated', v_updated,
                            'skipped', v_total - v_inserted - v_updated);
exception
  when invalid_text_representation or numeric_value_out_of_range or datatype_mismatch or invalid_parameter_value then
    perform private.fail('invalid_input', jsonb_build_object('field', 'items'));
end
$$;

-- Suggests approved catalogue entries for names typed in a pharmacy's own spreadsheet (top 3 per name).
-- Uses trigram *word similarity* (the typed name is short, the catalogue search text is long).
-- Only the client decides what to accept; nothing is written here.
create function public.match_medicine_names(p_names jsonb) returns table (
  idx integer, medicine_id uuid, name_ar text, name_en text, brand_name text, strength text,
  dosage_form text, score real
)
language plpgsql security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_uid uuid;
begin
  v_uid := private.assert_active_user();
  if not exists (
    select 1
    from public.pharmacy_members m
    join public.pharmacies ph on ph.id = m.pharmacy_id
    where m.user_id = v_uid and m.status = 'active'
      and m.role in ('owner', 'manager') and ph.approval_status = 'approved'
  ) then
    perform private.fail('forbidden');
  end if;
  if p_names is null or jsonb_typeof(p_names) <> 'array'
     or jsonb_array_length(p_names) = 0 or jsonb_array_length(p_names) > private.cfg_int('max_match_names') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'names'));
  end if;
  if exists (select 1 from jsonb_array_elements(p_names) e where jsonb_typeof(e) <> 'string') then
    perform private.fail('invalid_input', jsonb_build_object('field', 'names'));
  end if;
  -- Threshold of the `<%` operator (transaction-local); candidates below it are not even considered.
  perform set_config('pg_trgm.word_similarity_threshold', '0.4', true);

  return query
  select n.idx, c.id, c.name_ar, c.name_en, c.brand_name, c.strength, c.dosage_form, c.score
  from (
    select o.ord::integer as idx, left(private.normalize_search(o.val), 200) as q
    from jsonb_array_elements_text(p_names) with ordinality as o (val, ord)
  ) n
  cross join lateral (
    select m.id, m.name_ar, m.name_en, m.brand_name, m.strength, m.dosage_form,
           extensions.word_similarity(n.q, m.search_text)::real as score
    from public.medicines m
    where m.catalog_status = 'approved'
      and char_length(n.q) >= 3
      and n.q operator(extensions.<%) m.search_text
    order by extensions.word_similarity(n.q, m.search_text) desc,
             extensions.similarity(n.q, m.search_text) desc, m.id
    limit 3
  ) c
  order by n.idx, c.score desc;
end
$$;

-- ====================================================================================================
-- PART 20261011000006_rpc_pos_and_orders.sql
-- ====================================================================================================
-- Trusted functions: POS sales and the customer reservation lifecycle.
--
-- A "reservation" is the pharmacy's promise to prepare an order for `reservation_hours`; there are no
-- quantities in this system (docs/availability_design.md), so nothing is decremented or released.
--
-- Concurrency contract (see docs/database_schema.md §7):
--   * every state change locks the order row and re-reads its status after taking the lock
--   * the invoice counter row serialises invoice numbers per pharmacy

-- ---------------------------------------------------------------------------
-- JSON builders (call only after the caller has been authorised)
-- ---------------------------------------------------------------------------
create function private.sale_json(p_sale_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', s.id,
    'invoice_no', s.invoice_no,
    'order_id', s.order_id,
    'payment_method', s.payment_method,
    'currency', s.currency,
    'subtotal', s.subtotal,
    'discount_amount', s.discount_amount,
    'total', s.total,
    'created_at', s.created_at,
    'cashier_name', coalesce(pr.display_name, ''),
    'pharmacy', jsonb_build_object(
      'id', ph.id, 'name', ph.name, 'phone', ph.phone,
      'address_line', ph.address_line, 'neighborhood', ph.neighborhood, 'city', ph.city
    ),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'line_no', i.line_no, 'product_id', i.product_id, 'name', i.product_name,
        'strength', i.strength, 'quantity', i.quantity, 'unit_price', i.unit_price, 'line_total', i.line_total
      ) order by i.line_no)
      from public.sale_items i where i.sale_id = s.id
    ), '[]'::jsonb)
  )
  from public.sales s
  join public.pharmacies ph on ph.id = s.pharmacy_id
  left join public.profiles pr on pr.id = s.cashier_id
  where s.id = p_sale_id
$$;

create function private.order_json(p_order_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select to_jsonb(o) || jsonb_build_object(
    'pharmacy_name', ph.name,
    'items', coalesce((
      select jsonb_agg(to_jsonb(i) order by i.line_no)
      from public.order_items i where i.order_id = o.id
    ), '[]'::jsonb)
  )
  from public.orders o
  join public.pharmacies ph on ph.id = o.pharmacy_id
  where o.id = p_order_id
$$;

-- ---------------------------------------------------------------------------
-- Locking helpers
-- ---------------------------------------------------------------------------
create function private.lock_order_for_member(
  p_order_id uuid, p_roles public.member_role[], p_require_approved boolean
) returns public.orders
language plpgsql security definer set search_path = '' as $$
declare
  v_pharmacy uuid;
  v_order public.orders;
begin
  select o.pharmacy_id into v_pharmacy from public.orders o where o.id = p_order_id;
  if v_pharmacy is null then
    perform private.fail('not_found');
  end if;
  perform private.assert_member(v_pharmacy, p_roles, p_require_approved);
  select * into v_order from public.orders where id = p_order_id for update;
  return v_order;
end
$$;

-- ---------------------------------------------------------------------------
-- Reservation window
-- ---------------------------------------------------------------------------
-- Expires one order if (and only if) its reservation window has passed.
create function private.expire_order(p_order_id uuid) returns boolean
language plpgsql security definer set search_path = '' as $$
declare
  v_order public.orders;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found
     or v_order.status not in ('accepted', 'ready_for_pickup')
     or v_order.reservation_expires_at is null
     or v_order.reservation_expires_at > now() then
    return false;
  end if;
  update public.orders set status = 'expired', expired_at = now() where id = v_order.id;
  perform private.notify(v_order.customer_id, 'order_expired', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref));
  perform private.notify_pharmacy(v_order.pharmacy_id, 'order_expired', 'order', v_order.id,
                                  jsonb_build_object('ref', v_order.public_ref));
  return true;
end
$$;

-- SKIP LOCKED: an order another transaction is working on is simply left for the next run.
create function private.expire_pharmacy(p_pharmacy uuid) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  n integer := 0;
begin
  for v_id in
    select o.id from public.orders o
    where o.pharmacy_id = p_pharmacy
      and o.status in ('accepted', 'ready_for_pickup')
      and o.reservation_expires_at <= now()
    order by o.id
    for update skip locked
  loop
    if private.expire_order(v_id) then
      n := n + 1;
    end if;
  end loop;
  return n;
end
$$;

-- For pg_cron / service context only (not exposed to clients).
create function private.expire_all_reservations() returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  n integer := 0;
begin
  for v_id in
    select o.id from public.orders o
    where o.status in ('accepted', 'ready_for_pickup') and o.reservation_expires_at <= now()
    order by o.id
    for update skip locked
  loop
    if private.expire_order(v_id) then
      n := n + 1;
    end if;
  end loop;
  return n;
end
$$;

-- ---------------------------------------------------------------------------
-- POS
-- ---------------------------------------------------------------------------
create function public.create_pos_sale(
  p_pharmacy_id uuid,
  p_items jsonb,
  p_discount numeric,
  p_idempotency_key text
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_role public.member_role;
  v_hash text;
  v_prev jsonb;
  v_currency text;
  v_lines jsonb := '[]'::jsonb;
  v_subtotal numeric(14, 2) := 0;
  v_discount numeric(14, 2);
  v_total numeric(14, 2);
  v_sale_id uuid;
  v_inv integer;
  v_line integer := 0;
  r record;
  v_resp jsonb;
begin
  v_uid := private.assert_active_user();
  v_role := private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], true);

  v_hash := md5(coalesce(p_items::text, '') || ':' || coalesce(p_discount, 0)::text || ':' || p_pharmacy_id::text);
  v_prev := private.idem_begin(v_uid, 'pos_sale', p_idempotency_key, v_hash);
  if v_prev is not null then
    return v_prev;
  end if;

  if coalesce(p_discount, 0) < 0 or scale(coalesce(p_discount, 0)) > 2 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'discount'));
  end if;

  -- The shelf is the truth: any product of THIS pharmacy can be sold, whatever its "available" flag says.
  for r in
    select i.product_id, i.quantity, pp.pharmacy_id, pp.price,
           coalesce(nullif(btrim(m.name_ar), ''), m.name_en) as name, m.strength
    from private.parse_items(p_items, private.cfg_int('max_pos_lines'), private.cfg_int('max_pos_qty_per_item')) i
    left join public.pharmacy_products pp on pp.id = i.product_id
    left join public.medicines m on m.id = pp.medicine_id
    order by i.product_id
  loop
    if r.pharmacy_id is distinct from p_pharmacy_id then
      perform private.fail('product_unavailable', jsonb_build_object('product_id', r.product_id));
    end if;
    v_subtotal := v_subtotal + r.price * r.quantity;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'product_id', r.product_id, 'quantity', r.quantity, 'price', r.price,
      'name', r.name, 'strength', r.strength
    ));
  end loop;

  v_discount := coalesce(p_discount, 0);
  if v_discount > v_subtotal then
    perform private.fail('invalid_input', jsonb_build_object('field', 'discount', 'reason', 'exceeds_subtotal'));
  end if;
  if v_discount > 0 and v_role not in ('owner', 'manager') then
    perform private.fail('forbidden', jsonb_build_object('reason', 'discount'));
  end if;
  v_total := v_subtotal - v_discount;

  select ph.currency into v_currency from public.pharmacies ph where ph.id = p_pharmacy_id;

  insert into public.pharmacy_invoice_counters as c (pharmacy_id, last_number)
  values (p_pharmacy_id, 1)
  on conflict (pharmacy_id) do update set last_number = c.last_number + 1
  returning c.last_number into v_inv;

  insert into public.sales (pharmacy_id, invoice_no, currency, subtotal, discount_amount, total, cashier_id)
  values (p_pharmacy_id, 'INV-' || lpad(v_inv::text, 6, '0'), v_currency, v_subtotal, v_discount, v_total, v_uid)
  returning id into v_sale_id;

  for r in
    select x.product_id, x.quantity, x.price, x.name, x.strength
    from jsonb_to_recordset(v_lines) as x (product_id uuid, quantity integer, price numeric, name text, strength text)
    order by x.product_id
  loop
    v_line := v_line + 1;
    insert into public.sale_items (sale_id, line_no, product_id, product_name, strength, quantity, unit_price)
    values (v_sale_id, v_line, r.product_id, r.name, r.strength, r.quantity, r.price);
  end loop;

  if v_discount > 0 then
    perform private.audit('sale_discount', 'sale', v_sale_id, p_pharmacy_id,
                          jsonb_build_object('discount', v_discount, 'subtotal', v_subtotal));
  end if;

  v_resp := private.sale_json(v_sale_id);
  perform private.idem_finish(v_uid, 'pos_sale', p_idempotency_key, v_resp);
  return v_resp;
end
$$;

create function public.get_sale(p_sale_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_pharmacy uuid;
  v_cashier uuid;
  v_role public.member_role;
begin
  v_uid := private.assert_active_user();
  select s.pharmacy_id, s.cashier_id into v_pharmacy, v_cashier from public.sales s where s.id = p_sale_id;
  if v_pharmacy is null then
    perform private.fail('not_found');
  end if;
  -- Non-members (and cashiers looking at a colleague's sale) get not_found: no existence oracle.
  select m.role into v_role
  from public.pharmacy_members m
  where m.pharmacy_id = v_pharmacy and m.user_id = v_uid and m.status = 'active';
  if v_role is null or (v_role = 'cashier' and v_cashier is distinct from v_uid) then
    perform private.fail('not_found');
  end if;
  return private.sale_json(p_sale_id);
end
$$;

-- ---------------------------------------------------------------------------
-- Customer: create / cancel
-- ---------------------------------------------------------------------------
create function public.create_order(
  p_pharmacy_id uuid,
  p_items jsonb,
  p_notes text,
  p_contact_phone text,
  p_idempotency_key text
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_role public.user_role;
  v_name text;
  v_hash text;
  v_prev jsonb;
  v_ph public.pharmacies;
  v_lines jsonb := '[]'::jsonb;
  v_changes jsonb := '[]'::jsonb;
  v_subtotal numeric(14, 2) := 0;
  v_notes text := private.req_text(p_notes, 'notes', 1, 300, false);
  v_phone text;
  v_order public.orders;
  v_try integer := 0;
  v_line integer := 0;
  r record;
  v_resp jsonb;
begin
  v_uid := private.assert_active_user();
  -- Serialise one customer's order creation so the pending/hourly caps below cannot be beaten by
  -- parallel requests (the row lock is held until the transaction ends).
  select p.role, p.display_name into v_role, v_name from public.profiles p where p.id = v_uid for no key update;
  if v_role <> 'customer' then
    perform private.fail('forbidden');
  end if;

  v_hash := md5(coalesce(p_items::text, '') || ':' || coalesce(p_notes, '') || ':' ||
                coalesce(p_contact_phone, '') || ':' || p_pharmacy_id::text);
  v_prev := private.idem_begin(v_uid, 'create_order', p_idempotency_key, v_hash);
  if v_prev is not null then
    return v_prev;
  end if;

  if nullif(btrim(coalesce(p_contact_phone, '')), '') is not null then
    v_phone := private.clean_phone(p_contact_phone);
    if v_phone is null then
      perform private.fail('invalid_input', jsonb_build_object('field', 'contact_phone'));
    end if;
  end if;

  if (select count(*) from public.orders o where o.customer_id = v_uid and o.status = 'pending')
       >= private.cfg_int('max_pending_orders') then
    perform private.fail('too_many_pending');
  end if;
  if (select count(*) from public.orders o
      where o.customer_id = v_uid and o.created_at > now() - interval '1 hour')
       >= private.cfg_int('max_orders_per_hour') then
    perform private.fail('rate_limited');
  end if;

  select * into v_ph from public.pharmacies ph where ph.id = p_pharmacy_id;
  if not found or v_ph.approval_status <> 'approved' or not v_ph.is_listed then
    perform private.fail('pharmacy_not_active');
  end if;

  for r in
    select i.product_id, i.quantity, i.expected_unit_price,
           pp.pharmacy_id, pp.price, pp.is_available,
           m.id as medicine_id, m.catalog_status, m.strength, m.dosage_form,
           coalesce(nullif(btrim(m.name_ar), ''), m.name_en) as name
    from private.parse_items(p_items, private.cfg_int('max_order_lines'), private.cfg_int('max_customer_qty_per_item')) i
    left join public.pharmacy_products pp on pp.id = i.product_id
    left join public.medicines m on m.id = pp.medicine_id
    order by i.product_id
  loop
    if r.pharmacy_id is distinct from p_pharmacy_id
       or not coalesce(r.is_available, false)
       or r.catalog_status is distinct from 'approved'::public.catalog_status then
      perform private.fail('product_unavailable', jsonb_build_object('product_id', r.product_id, 'name', r.name));
    end if;
    if r.expected_unit_price is not null and r.expected_unit_price <> r.price then
      v_changes := v_changes || jsonb_build_array(jsonb_build_object(
        'product_id', r.product_id, 'name', r.name, 'expected', r.expected_unit_price, 'current', r.price
      ));
    end if;
    v_subtotal := v_subtotal + r.price * r.quantity;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'product_id', r.product_id, 'medicine_id', r.medicine_id, 'name', r.name, 'strength', r.strength,
      'dosage_form', r.dosage_form, 'quantity', r.quantity, 'price', r.price
    ));
  end loop;

  if jsonb_array_length(v_changes) > 0 then
    perform private.fail('price_changed', jsonb_build_object('items', v_changes));
  end if;

  loop
    begin
      insert into public.orders (public_ref, customer_id, pharmacy_id, currency, subtotal, customer_name,
                                 contact_phone, customer_notes, pharmacy_name, pharmacy_address, pharmacy_phone)
      values (private.generate_order_ref(), v_uid, p_pharmacy_id, v_ph.currency, v_subtotal,
              coalesce(v_name, ''), v_phone, v_notes, v_ph.name,
              concat_ws('، ', nullif(btrim(v_ph.address_line), ''), nullif(btrim(v_ph.neighborhood), ''), nullif(btrim(v_ph.city), '')),
              case when v_ph.show_phone_publicly then v_ph.phone else null end)
      returning * into v_order;
      exit;
    exception when unique_violation then
      v_try := v_try + 1;
      if v_try >= 5 then
        raise exception using errcode = 'P0001', message = 'internal_error', detail = 'order_ref_collision';
      end if;
    end;
  end loop;

  for r in
    select x.product_id, x.medicine_id, x.name, x.strength, x.dosage_form, x.quantity, x.price
    from jsonb_to_recordset(v_lines) as x (
      product_id uuid, medicine_id uuid, name text, strength text, dosage_form text, quantity integer, price numeric
    )
    order by x.product_id
  loop
    v_line := v_line + 1;
    insert into public.order_items (order_id, line_no, product_id, medicine_id, medicine_name, strength,
                                    dosage_form, quantity, unit_price)
    values (v_order.id, v_line, r.product_id, r.medicine_id, r.name, r.strength, r.dosage_form, r.quantity, r.price);
  end loop;

  perform private.notify_pharmacy(p_pharmacy_id, 'order_new', 'order', v_order.id,
                                  jsonb_build_object('ref', v_order.public_ref));

  v_resp := private.order_json(v_order.id);
  perform private.idem_finish(v_uid, 'create_order', p_idempotency_key, v_resp);
  return v_resp;
end
$$;

create function public.cancel_order(p_order_id uuid, p_reason text default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_owner uuid;
  v_order public.orders;
  v_reason text := private.req_text(p_reason, 'reason', 1, 300, false);
begin
  v_uid := private.assert_active_user();
  select o.customer_id into v_owner from public.orders o where o.id = p_order_id;
  if v_owner is null or v_owner <> v_uid then
    perform private.fail('not_found');
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status not in ('pending', 'accepted', 'ready_for_pickup', 'expired') then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'cancelled'));
  end if;

  update public.orders
  set status = 'cancelled', cancelled_at = now(), cancelled_by_role = 'customer', cancel_reason = v_reason
  where id = v_order.id;

  perform private.notify_pharmacy(v_order.pharmacy_id, 'order_cancelled', 'order', v_order.id,
                                  jsonb_build_object('ref', v_order.public_ref, 'by', 'customer'));
  return private.order_json(v_order.id);
end
$$;

-- ---------------------------------------------------------------------------
-- Pharmacy: handle the reservation
-- ---------------------------------------------------------------------------
create function public.accept_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_pharmacy uuid;
  v_order public.orders;
  v_expires timestamptz;
begin
  perform private.assert_active_user();
  select o.pharmacy_id into v_pharmacy from public.orders o where o.id = p_order_id;
  if v_pharmacy is null then
    perform private.fail('not_found');
  end if;
  perform private.assert_member(v_pharmacy, array['owner', 'manager', 'cashier']::public.member_role[], true);

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status <> 'pending' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'accepted'));
  end if;

  v_expires := now() + make_interval(hours => private.cfg_int('reservation_hours'));

  update public.orders
  set status = 'accepted', accepted_at = now(), reservation_expires_at = v_expires
  where id = v_order.id;

  perform private.notify(v_order.customer_id, 'order_accepted', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref, 'expires_at', v_expires));
  return private.order_json(v_order.id);
end
$$;

create function public.reject_order(p_order_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_order public.orders;
  v_reason text := private.req_text(p_reason, 'reason', 3, 300);
begin
  perform private.assert_active_user();
  v_order := private.lock_order_for_member(
    p_order_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  if v_order.status <> 'pending' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'rejected'));
  end if;
  update public.orders set status = 'rejected', rejected_at = now(), reject_reason = v_reason
  where id = v_order.id;
  perform private.notify(v_order.customer_id, 'order_rejected', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref, 'reason', v_reason));
  return private.order_json(v_order.id);
end
$$;

create function public.mark_order_ready(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_order public.orders;
begin
  perform private.assert_active_user();
  v_order := private.lock_order_for_member(
    p_order_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  if v_order.status <> 'accepted' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'ready_for_pickup'));
  end if;
  if v_order.reservation_expires_at <= now() then
    perform private.fail('reservation_expired');
  end if;
  update public.orders set status = 'ready_for_pickup', ready_at = now() where id = v_order.id;
  perform private.notify(v_order.customer_id, 'order_ready', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref, 'expires_at', v_order.reservation_expires_at));
  return private.order_json(v_order.id);
end
$$;

create function public.pharmacy_cancel_order(p_order_id uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_order public.orders;
  v_reason text := private.req_text(p_reason, 'reason', 3, 300);
begin
  perform private.assert_active_user();
  v_order := private.lock_order_for_member(
    p_order_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  if v_order.status not in ('accepted', 'ready_for_pickup') then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'cancelled'));
  end if;
  update public.orders
  set status = 'cancelled', cancelled_at = now(), cancelled_by_role = 'pharmacy', cancel_reason = v_reason
  where id = v_order.id;
  perform private.notify(v_order.customer_id, 'order_cancelled', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref, 'by', 'pharmacy', 'reason', v_reason));
  return private.order_json(v_order.id);
end
$$;

-- Handover: verifies the reference, then in ONE transaction records the sale and completes the order.
-- Safe to retry.
create function public.complete_order(p_order_id uuid, p_reference text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_order public.orders;
  v_sale_id uuid;
  v_inv integer;
begin
  v_uid := private.assert_active_user();
  v_order := private.lock_order_for_member(
    p_order_id, array['owner', 'manager', 'cashier']::public.member_role[], true);

  if upper(btrim(coalesce(p_reference, ''))) <> v_order.public_ref then
    perform private.fail('reference_mismatch');
  end if;

  if v_order.status = 'completed' then
    select s.id into v_sale_id from public.sales s where s.order_id = v_order.id;
    return private.sale_json(v_sale_id);
  end if;
  if v_order.status <> 'ready_for_pickup' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'completed'));
  end if;
  if v_order.reservation_expires_at <= now() then
    perform private.fail('reservation_expired');
  end if;

  insert into public.pharmacy_invoice_counters as c (pharmacy_id, last_number)
  values (v_order.pharmacy_id, 1)
  on conflict (pharmacy_id) do update set last_number = c.last_number + 1
  returning c.last_number into v_inv;

  insert into public.sales (pharmacy_id, invoice_no, order_id, currency, subtotal, discount_amount, total, cashier_id)
  values (v_order.pharmacy_id, 'INV-' || lpad(v_inv::text, 6, '0'), v_order.id, v_order.currency,
          v_order.subtotal, 0, v_order.subtotal, v_uid)
  returning id into v_sale_id;

  insert into public.sale_items (sale_id, line_no, product_id, product_name, strength, quantity, unit_price)
  select v_sale_id, oi.line_no, oi.product_id, oi.medicine_name, oi.strength, oi.quantity, oi.unit_price
  from public.order_items oi where oi.order_id = v_order.id;

  update public.orders set status = 'completed', completed_at = now() where id = v_order.id;
  perform private.notify(v_order.customer_id, 'order_completed', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref));
  return private.sale_json(v_sale_id);
end
$$;

-- An expired order may be put back in play by the pharmacy (it promises to prepare it again).
create function public.reactivate_order(p_order_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_pharmacy uuid;
  v_order public.orders;
  v_expires timestamptz;
begin
  perform private.assert_active_user();
  select o.pharmacy_id into v_pharmacy from public.orders o where o.id = p_order_id;
  if v_pharmacy is null then
    perform private.fail('not_found');
  end if;
  perform private.assert_member(v_pharmacy, array['owner', 'manager', 'cashier']::public.member_role[], true);
  perform private.expire_pharmacy(v_pharmacy);

  select * into v_order from public.orders where id = p_order_id for update;
  if v_order.status <> 'expired' then
    perform private.fail('invalid_transition', jsonb_build_object('from', v_order.status, 'to', 'accepted'));
  end if;

  v_expires := now() + make_interval(hours => private.cfg_int('reservation_hours'));
  update public.orders
  set status = 'accepted', accepted_at = now(), ready_at = null, reservation_expires_at = v_expires
  where id = v_order.id;

  perform private.notify(v_order.customer_id, 'order_reactivated', 'order', v_order.id,
                         jsonb_build_object('ref', v_order.public_ref, 'expires_at', v_expires));
  return private.order_json(v_order.id);
end
$$;

create function public.find_order_by_ref(p_pharmacy_id uuid, p_ref text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], false);
  select o.id into v_id
  from public.orders o
  where o.pharmacy_id = p_pharmacy_id and o.public_ref = upper(btrim(coalesce(p_ref, '')));
  if v_id is null then
    perform private.fail('not_found');
  end if;
  return private.order_json(v_id);
end
$$;

-- Members trigger expiry for their own pharmacy (the app calls it when the orders screen opens).
create function public.expire_reservations(p_pharmacy_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], false);
  return jsonb_build_object('expired', private.expire_pharmacy(p_pharmacy_id));
end
$$;

-- ====================================================================================================
-- PART 20261011000007_rpc_availability_requests.sql
-- ====================================================================================================
-- "Ask the pharmacies nearby": availability requests (docs/availability_design.md).
--
-- Concurrency contract: every function that changes a request locks the request row first
-- (FOR UPDATE) and then its target rows; the expansion rule runs under that lock.
-- Clients have no direct access to availability_requests / availability_targets.

-- ---------------------------------------------------------------------------
-- Geography
-- ---------------------------------------------------------------------------
-- Approved, listed pharmacies with a location within p_radius_km of a point (bounding-box prefilter + exact distance).
create function private.pharmacies_within(
  p_lat double precision, p_lng double precision, p_radius_km double precision
) returns table (pharmacy_id uuid, distance_km double precision)
language sql stable security definer set search_path = '' as $$
  select t.id, t.d
  from (
    select ph.id, private.distance_km(p_lat, p_lng, ph.latitude, ph.longitude) as d
    from public.pharmacies ph
    where ph.approval_status = 'approved' and ph.is_listed and ph.latitude is not null
      and ph.latitude between p_lat - p_radius_km / 111.0 and p_lat + p_radius_km / 111.0
      and ph.longitude between p_lng - p_radius_km / (111.0 * greatest(cos(radians(p_lat)), 0.01))
                           and p_lng + p_radius_km / (111.0 * greatest(cos(radians(p_lat)), 0.01))
  ) t
  where t.d <= p_radius_km
$$;

-- ---------------------------------------------------------------------------
-- Targets and expansion
-- ---------------------------------------------------------------------------
-- Adds (and notifies) the pharmacies inside the radius of `p_step` that were not targeted yet,
-- nearest first, never exceeding max_request_targets in total. Returns how many were added.
create function private.add_request_targets(p_request_id uuid, p_step integer) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  r public.availability_requests;
  v_room integer;
  v_added integer := 0;
  v_name text;
  t record;
begin
  select * into r from public.availability_requests where id = p_request_id;
  select private.cfg_int('max_request_targets') - count(*) into v_room
  from public.availability_targets x where x.request_id = p_request_id;
  if v_room <= 0 then
    return 0;
  end if;
  select coalesce(nullif(btrim(m.name_ar), ''), m.name_en) into v_name
  from public.medicines m where m.id = r.medicine_id;

  for t in
    select w.pharmacy_id, w.distance_km
    from private.pharmacies_within(r.latitude, r.longitude, private.request_radius_km(p_step)) w
    where not exists (
      select 1 from public.availability_targets x
      where x.request_id = p_request_id and x.pharmacy_id = w.pharmacy_id
    )
    order by w.distance_km, w.pharmacy_id
    limit v_room
  loop
    insert into public.availability_targets (request_id, pharmacy_id, step, distance_km)
    values (p_request_id, t.pharmacy_id, p_step, round(t.distance_km::numeric, 2));
    perform private.notify_pharmacy(t.pharmacy_id, 'availability_request', 'availability_request', p_request_id,
                                    jsonb_build_object('medicine', v_name));
    v_added := v_added + 1;
  end loop;
  return v_added;
end
$$;

-- Applies the lifecycle rules to one request (caller should hold the row lock):
--   * past expires_at            -> 'expired'
--   * somebody answered available -> nothing to do
--   * otherwise the radius is widened one step when the current radius has no pharmacy, every notified
--     pharmacy answered "unavailable", or request_wait_minutes passed since the last step.
create function private.advance_request(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare
  r public.availability_requests;
  v_total integer;
  v_answered integer;
  v_available integer;
begin
  loop
    select * into r from public.availability_requests where id = p_id for update;
    if not found or r.status <> 'open' then
      return;
    end if;
    if r.expires_at <= now() then
      update public.availability_requests set status = 'expired', closed_at = now() where id = p_id;
      return;
    end if;
    select count(*), count(*) filter (where t.answer is not null), count(*) filter (where t.answer = 'available')
    into v_total, v_answered, v_available
    from public.availability_targets t where t.request_id = p_id;

    if v_available > 0 or r.step >= private.cfg_int('request_max_step') then
      return;
    end if;
    if v_total = 0 or v_answered = v_total
       or r.last_expanded_at <= now() - make_interval(mins => private.cfg_int('request_wait_minutes')) then
      update public.availability_requests
      set step = r.step + 1, last_expanded_at = now()
      where id = p_id;
      perform private.add_request_targets(p_id, r.step + 1);
    else
      return;
    end if;
  end loop;
end
$$;

-- Maintenance for pg_cron (every minute is plenty): expands / expires open requests and deletes old ones.
create function private.advance_all_availability_requests() returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_id uuid;
  n integer := 0;
begin
  for v_id in
    select r.id from public.availability_requests r where r.status = 'open' order by r.id for update skip locked
  loop
    perform private.advance_request(v_id);
    n := n + 1;
  end loop;
  delete from public.availability_requests where created_at < now() - interval '30 days';
  return n;
end
$$;

-- ---------------------------------------------------------------------------
-- JSON for the customer (call only after the caller was authorised as the request's owner)
-- ---------------------------------------------------------------------------
create function private.request_json(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  r public.availability_requests;
  v_status text;
begin
  select * into r from public.availability_requests where id = p_id;
  v_status := case when r.status = 'open' and r.expires_at <= now() then 'expired' else r.status::text end;
  return jsonb_build_object(
    'id', r.id,
    'status', v_status,
    'step', r.step,
    'radius_km', private.request_radius_km(r.step),
    'radius_exhausted', r.step >= private.cfg_int('request_max_step'),
    'created_at', r.created_at,
    'expires_at', r.expires_at,
    'seconds_left', case when v_status = 'open' then greatest(0, extract(epoch from r.expires_at - now()))::integer else 0 end,
    'medicine', (
      select jsonb_build_object('id', m.id, 'name_ar', m.name_ar, 'name_en', m.name_en,
                                'brand_name', m.brand_name, 'strength', m.strength, 'dosage_form', m.dosage_form)
      from public.medicines m where m.id = r.medicine_id
    ),
    'notified', (select count(*) from public.availability_targets t where t.request_id = r.id),
    'answered', (select count(*) from public.availability_targets t where t.request_id = r.id and t.answer is not null),
    'unavailable', (select count(*) from public.availability_targets t where t.request_id = r.id and t.answer = 'unavailable'),
    'offers', coalesce((
      select jsonb_agg(o order by o.distance_km, o.price, o.pharmacy_id)
      from (
        select ph.id as pharmacy_id, ph.name, ph.address_line, ph.neighborhood, ph.city,
               case when ph.show_phone_publicly then ph.phone else null end as phone,
               ph.latitude, ph.longitude, t.distance_km, t.price, ph.currency, t.answered_at,
               pp.id as product_id
        from public.availability_targets t
        join public.pharmacies ph on ph.id = t.pharmacy_id
        left join public.pharmacy_products pp on pp.pharmacy_id = ph.id and pp.medicine_id = r.medicine_id
        where t.request_id = r.id and t.answer = 'available'
          and ph.approval_status = 'approved' and ph.is_listed
      ) o
    ), '[]'::jsonb)
  );
end
$$;

-- Locks a request owned by the caller (customer); `not_found` otherwise (no existence oracle).
create function private.lock_own_request(p_id uuid) returns public.availability_requests
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := private.assert_active_user();
  v_owner uuid;
  r public.availability_requests;
begin
  select q.customer_id into v_owner from public.availability_requests q where q.id = p_id;
  if v_owner is null or v_owner <> v_uid then
    perform private.fail('not_found');
  end if;
  select * into r from public.availability_requests where id = p_id for update;
  return r;
end
$$;

-- ---------------------------------------------------------------------------
-- Customer API
-- ---------------------------------------------------------------------------
create function public.create_availability_request(
  p_medicine_id uuid,
  p_latitude double precision,
  p_longitude double precision,
  p_idempotency_key text
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_role public.user_role;
  v_lat double precision;
  v_lng double precision;
  v_hash text;
  v_prev jsonb;
  v_existing uuid;
  v_req public.availability_requests;
  v_resp jsonb;
begin
  v_uid := private.assert_active_user();
  -- Serialises one customer's requests so the caps below cannot be beaten by parallel calls.
  select p.role into v_role from public.profiles p where p.id = v_uid for no key update;
  if v_role <> 'customer' then
    perform private.fail('forbidden');
  end if;
  perform private.check_location(p_latitude, p_longitude);
  if p_medicine_id is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'medicine_id'));
  end if;
  v_lat := round(p_latitude::numeric, 3)::double precision;
  v_lng := round(p_longitude::numeric, 3)::double precision;

  v_hash := md5(p_medicine_id::text || ':' || v_lat::text || ':' || v_lng::text);
  v_prev := private.idem_begin(v_uid, 'create_request', p_idempotency_key, v_hash);
  if v_prev is not null then
    return v_prev;
  end if;

  if not exists (select 1 from public.medicines m where m.id = p_medicine_id and m.catalog_status = 'approved') then
    perform private.fail('not_found', jsonb_build_object('field', 'medicine_id'));
  end if;

  -- Same medicine from (nearly) the same spot while a request is still alive: reuse it.
  select q.id into v_existing
  from public.availability_requests q
  where q.customer_id = v_uid and q.medicine_id = p_medicine_id
    and q.status = 'open' and q.expires_at > now()
    and q.created_at > now() - make_interval(mins => private.cfg_int('request_dedupe_minutes'))
    and private.distance_km(q.latitude, q.longitude, v_lat, v_lng) < 0.5
  order by q.created_at desc
  limit 1;
  if v_existing is not null then
    select * into v_req from public.availability_requests where id = v_existing for update;
    perform private.advance_request(v_existing);
    v_resp := private.request_json(v_existing);
    perform private.idem_finish(v_uid, 'create_request', p_idempotency_key, v_resp);
    return v_resp;
  end if;

  if (select count(*) from public.availability_requests q
      where q.customer_id = v_uid and q.status = 'open' and q.expires_at > now())
       >= private.cfg_int('max_open_requests') then
    perform private.fail('too_many_requests');
  end if;
  if (select count(*) from public.availability_requests q
      where q.customer_id = v_uid and q.created_at > now() - interval '1 hour')
       >= private.cfg_int('max_requests_per_hour') then
    perform private.fail('rate_limited');
  end if;

  insert into public.availability_requests (customer_id, medicine_id, latitude, longitude, expires_at)
  values (v_uid, p_medicine_id, v_lat, v_lng, now() + make_interval(mins => private.cfg_int('request_ttl_minutes')))
  returning * into v_req;

  perform private.add_request_targets(v_req.id, 1);
  perform private.advance_request(v_req.id);

  v_resp := private.request_json(v_req.id);
  perform private.idem_finish(v_uid, 'create_request', p_idempotency_key, v_resp);
  return v_resp;
end
$$;

-- Polled by the customer's screen: also applies the expansion / expiry rules.
create function public.get_availability_request(p_request_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.availability_requests;
begin
  r := private.lock_own_request(p_request_id);
  perform private.advance_request(r.id);
  return private.request_json(r.id);
end
$$;

create function public.list_my_availability_requests(p_limit integer default 20, p_offset integer default 0)
returns table (
  id uuid, medicine_id uuid, name_ar text, name_en text, strength text, dosage_form text,
  status text, created_at timestamptz, expires_at timestamptz, offers_count integer
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_uid uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  v_uid := private.assert_active_user();
  return query
  select q.id, q.medicine_id, m.name_ar, m.name_en, m.strength, m.dosage_form,
         case when q.status = 'open' and q.expires_at <= now() then 'expired' else q.status::text end,
         q.created_at, q.expires_at,
         (select count(*)::integer from public.availability_targets t
          where t.request_id = q.id and t.answer = 'available')
  from public.availability_requests q
  join public.medicines m on m.id = q.medicine_id
  where q.customer_id = v_uid
  order by q.created_at desc, q.id
  limit v_limit offset v_offset;
end
$$;

-- "Search further": widens the radius by one step (also done automatically, see advance_request).
create function public.expand_availability_request(p_request_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.availability_requests;
begin
  r := private.lock_own_request(p_request_id);
  perform private.advance_request(r.id);
  select * into r from public.availability_requests where id = r.id;
  if r.status = 'closed' then
    perform private.fail('request_closed');
  end if;
  if r.status = 'expired' or r.expires_at <= now() then
    return private.request_json(r.id);
  end if;
  if r.step >= private.cfg_int('request_max_step') then
    perform private.fail('invalid_transition', jsonb_build_object('reason', 'max_radius'));
  end if;
  update public.availability_requests set step = r.step + 1, last_expanded_at = now() where id = r.id;
  perform private.add_request_targets(r.id, r.step + 1);
  perform private.advance_request(r.id);
  return private.request_json(r.id);
end
$$;

create function public.close_availability_request(p_request_id uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.availability_requests;
begin
  r := private.lock_own_request(p_request_id);
  if r.status = 'open' and r.expires_at > now() then
    update public.availability_requests set status = 'closed', closed_at = now() where id = r.id;
  end if;
  return private.request_json(r.id);
end
$$;

-- ---------------------------------------------------------------------------
-- Pharmacy API (inbox + answer). Pharmacies never see who asked or where the customer is.
-- ---------------------------------------------------------------------------
create function private.open_request_count(p_pharmacy_id uuid) returns integer
language sql stable security definer set search_path = '' as $$
  select count(*)::integer
  from public.availability_targets t
  join public.availability_requests r on r.id = t.request_id
  where t.pharmacy_id = p_pharmacy_id and t.answer is null
    and r.status = 'open' and r.expires_at > now()
$$;

create function public.count_pharmacy_availability_requests(p_pharmacy_id uuid) returns integer
language plpgsql stable security definer set search_path = '' as $$
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  return private.open_request_count(p_pharmacy_id);
end
$$;

create function public.list_pharmacy_availability_requests(
  p_pharmacy_id uuid,
  p_only_open boolean default true,
  p_limit integer default 30,
  p_offset integer default 0
) returns table (
  request_id uuid, medicine_id uuid, name_ar text, name_en text, brand_name text, strength text,
  dosage_form text, distance_km numeric, created_at timestamptz, expires_at timestamptz,
  request_status text, answer text, answer_price numeric, answered_at timestamptz,
  listed_price numeric, listed_available boolean
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  return query
  select r.id, m.id, m.name_ar, m.name_en, m.brand_name, m.strength, m.dosage_form,
         t.distance_km, r.created_at, r.expires_at,
         case when r.status = 'open' and r.expires_at <= now() then 'expired' else r.status::text end,
         t.answer::text, t.price, t.answered_at,
         pp.price, pp.is_available
  from public.availability_targets t
  join public.availability_requests r on r.id = t.request_id
  join public.medicines m on m.id = r.medicine_id
  left join public.pharmacy_products pp on pp.pharmacy_id = t.pharmacy_id and pp.medicine_id = r.medicine_id
  where t.pharmacy_id = p_pharmacy_id
    and (
      (p_only_open and r.status = 'open' and r.expires_at > now())
      or (not p_only_open and t.notified_at > now() - interval '7 days')
    )
  order by (t.answer is null and r.status = 'open' and r.expires_at > now()) desc, t.notified_at desc, r.id
  limit v_limit offset v_offset;
end
$$;

-- Answer "available" (with price) or "unavailable". May be repeated while the request is open.
-- Owners/managers' answers also keep the pharmacy list up to date; a cashier's answer only answers.
create function public.answer_availability_request(
  p_pharmacy_id uuid,
  p_request_id uuid,
  p_available boolean,
  p_price numeric default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid;
  v_role public.member_role;
  r public.availability_requests;
  v_target public.availability_targets;
  v_first boolean;
  v_med_name text;
  v_ph_name text;
begin
  v_uid := private.assert_active_user();
  v_role := private.assert_member(p_pharmacy_id, array['owner', 'manager', 'cashier']::public.member_role[], true);
  if p_available is null then
    perform private.fail('invalid_input', jsonb_build_object('field', 'available'));
  end if;
  if p_available and (p_price is null or p_price <= 0 or p_price > 999999999999 or scale(p_price) > 2) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'price'));
  end if;

  select * into r from public.availability_requests where id = p_request_id for update;
  if not found then
    perform private.fail('not_found');
  end if;
  select * into v_target from public.availability_targets t
  where t.request_id = p_request_id and t.pharmacy_id = p_pharmacy_id for update;
  if not found then
    perform private.fail('not_found');
  end if;
  if r.status <> 'open' or r.expires_at <= now() then
    perform private.fail('request_closed');
  end if;

  v_first := p_available and not exists (
    select 1 from public.availability_targets t where t.request_id = p_request_id and t.answer = 'available'
  );

  update public.availability_targets set
    answer = case when p_available then 'available'::public.request_answer else 'unavailable'::public.request_answer end,
    price = case when p_available then p_price else null end,
    answered_by = v_uid,
    answered_at = now()
  where request_id = p_request_id and pharmacy_id = p_pharmacy_id
  returning * into v_target;

  -- The pharmacy list learns from the answer (owners and managers only: cashiers cannot change prices).
  if v_role in ('owner', 'manager') then
    if p_available then
      insert into public.pharmacy_products as pp (pharmacy_id, medicine_id, price, is_available, confirmed_at)
      values (p_pharmacy_id, r.medicine_id, p_price, true, now())
      on conflict (pharmacy_id, medicine_id) do update
        set price = excluded.price, is_available = true, confirmed_at = now();
    else
      update public.pharmacy_products
      set is_available = false, confirmed_at = now()
      where pharmacy_id = p_pharmacy_id and medicine_id = r.medicine_id;
    end if;
  end if;

  if v_first then
    select coalesce(nullif(btrim(m.name_ar), ''), m.name_en) into v_med_name
    from public.medicines m where m.id = r.medicine_id;
    select ph.name into v_ph_name from public.pharmacies ph where ph.id = p_pharmacy_id;
    perform private.notify(r.customer_id, 'availability_found', 'availability_request', r.id,
                           jsonb_build_object('medicine', v_med_name, 'pharmacy', v_ph_name));
  end if;

  return jsonb_build_object(
    'request_id', p_request_id, 'pharmacy_id', p_pharmacy_id,
    'answer', v_target.answer, 'price', v_target.price, 'answered_at', v_target.answered_at
  );
end
$$;

-- ====================================================================================================
-- PART 20261011000008_rpc_public_and_dashboard.sql
-- ====================================================================================================
-- Customer-facing reads (masked, paginated) and the pharmacy dashboard.
-- Customers never read pharmacies / pharmacy_products directly; these functions expose only what is public.
-- "Available" = the pharmacy marked it available AND confirmed it within listing_max_age_days.

-- ---------------------------------------------------------------------------
-- Medicine search (normalised Arabic/Latin substring match, trigram-indexed)
-- ---------------------------------------------------------------------------
create function public.search_medicines(
  p_query text,
  p_category_id uuid default null,
  p_dosage_form text default null,
  p_limit integer default 20,
  p_offset integer default 0
) returns table (
  id uuid, name_ar text, name_en text, brand_name text, active_ingredient text, strength text,
  dosage_form text, package_description text, category_id uuid, pharmacy_count integer
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_q text;
  v_tokens text[];
  v_p1 text := '%';
  v_p2 text := '%';
  v_p3 text := '%';
  v_p4 text := '%';
  v_form text := nullif(private.normalize_search(p_dosage_form), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  perform private.assert_active_user();
  v_q := left(private.normalize_search(p_query), 100);
  if char_length(v_q) < 2 then
    return;
  end if;
  v_tokens := regexp_split_to_array(v_q, ' ');
  v_p1 := '%' || private.like_escape(v_tokens[1]) || '%';
  if array_length(v_tokens, 1) >= 2 then v_p2 := '%' || private.like_escape(v_tokens[2]) || '%'; end if;
  if array_length(v_tokens, 1) >= 3 then v_p3 := '%' || private.like_escape(v_tokens[3]) || '%'; end if;
  if array_length(v_tokens, 1) >= 4 then v_p4 := '%' || private.like_escape(v_tokens[4]) || '%'; end if;

  return query
  select m.id, m.name_ar, m.name_en, m.brand_name, m.active_ingredient, m.strength, m.dosage_form,
         m.package_description, m.category_id,
         (select count(*)::integer
          from public.pharmacy_products pp
          join public.pharmacies ph on ph.id = pp.pharmacy_id
          where pp.medicine_id = m.id and pp.is_available
            and pp.confirmed_at >= now() - make_interval(days => private.cfg_int('listing_max_age_days'))
            and ph.approval_status = 'approved' and ph.is_listed) as pharmacy_count
  from public.medicines m
  where m.catalog_status = 'approved'
    and m.search_text like v_p1
    and m.search_text like v_p2
    and m.search_text like v_p3
    and m.search_text like v_p4
    and (p_category_id is null or m.category_id = p_category_id)
    and (v_form is null or private.normalize_search(m.dosage_form) = v_form)
  order by (m.search_text like private.like_escape(v_tokens[1]) || '%') desc,
           extensions.similarity(m.search_text, v_q) desc,
           m.id
  limit v_limit offset v_offset;
end
$$;

-- ---------------------------------------------------------------------------
-- Pharmacies that list a medicine as available (confirmed recently), nearest first when a location is given
-- ---------------------------------------------------------------------------
create function public.get_medicine_pharmacies(
  p_medicine_id uuid,
  p_latitude double precision default null,
  p_longitude double precision default null,
  p_radius_km double precision default null,
  p_city text default null,
  p_limit integer default 20,
  p_offset integer default 0
) returns table (
  pharmacy_id uuid, pharmacy_name text, city text, neighborhood text, address_line text, phone text,
  latitude double precision, longitude double precision, distance_km double precision,
  product_id uuid, price numeric, currency text, confirmed_at timestamptz, freshness text
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_city text := nullif(private.normalize_search(p_city), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_located boolean := p_latitude is not null or p_longitude is not null;
begin
  perform private.assert_active_user();
  if v_located then
    perform private.check_location(p_latitude, p_longitude);
  end if;
  if p_radius_km is not null and (not v_located or p_radius_km <= 0 or p_radius_km > 50) then
    perform private.fail('invalid_input', jsonb_build_object('field', 'radius_km'));
  end if;
  return query
  select t.pharmacy_id, t.pharmacy_name, t.city, t.neighborhood, t.address_line, t.phone,
         t.latitude, t.longitude, t.distance_km, t.product_id, t.price, t.currency, t.confirmed_at, t.freshness
  from (
    select ph.id as pharmacy_id, ph.name as pharmacy_name, ph.city, ph.neighborhood, ph.address_line,
           case when ph.show_phone_publicly then ph.phone else null end as phone,
           ph.latitude, ph.longitude,
           case when v_located and ph.latitude is not null
                then round(private.distance_km(p_latitude, p_longitude, ph.latitude, ph.longitude)::numeric, 2)::double precision
           end as distance_km,
           pp.id as product_id, pp.price, ph.currency, pp.confirmed_at,
           private.listing_freshness(pp.confirmed_at) as freshness
    from public.pharmacy_products pp
    join public.pharmacies ph on ph.id = pp.pharmacy_id
    join public.medicines m on m.id = pp.medicine_id
    where pp.medicine_id = p_medicine_id and pp.is_available
      and pp.confirmed_at >= now() - make_interval(days => private.cfg_int('listing_max_age_days'))
      and ph.approval_status = 'approved' and ph.is_listed
      and m.catalog_status = 'approved'
      and (v_city is null or private.normalize_search(ph.city) = v_city)
  ) t
  where p_radius_km is null or (t.distance_km is not null and t.distance_km <= p_radius_km)
  order by t.distance_km nulls last,
           (t.freshness = 'recent') desc,
           t.price, t.pharmacy_name, t.pharmacy_id
  limit v_limit offset v_offset;
end
$$;

-- ---------------------------------------------------------------------------
-- Public pharmacy directory
-- ---------------------------------------------------------------------------
create function public.list_public_pharmacies(
  p_query text default null,
  p_city text default null,
  p_limit integer default 20,
  p_offset integer default 0,
  p_latitude double precision default null,
  p_longitude double precision default null
) returns table (
  id uuid, name text, city text, neighborhood text, address_line text, phone text, currency text,
  latitude double precision, longitude double precision, distance_km double precision
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_q text := nullif(private.normalize_search(p_query), '');
  v_city text := nullif(private.normalize_search(p_city), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_located boolean := p_latitude is not null or p_longitude is not null;
begin
  perform private.assert_active_user();
  if v_located then
    perform private.check_location(p_latitude, p_longitude);
  end if;
  return query
  select t.id, t.name, t.city, t.neighborhood, t.address_line, t.phone, t.currency,
         t.latitude, t.longitude, t.distance_km
  from (
    select ph.id, ph.name, ph.city, ph.neighborhood, ph.address_line,
           case when ph.show_phone_publicly then ph.phone else null end as phone, ph.currency,
           ph.latitude, ph.longitude,
           case when v_located and ph.latitude is not null
                then round(private.distance_km(p_latitude, p_longitude, ph.latitude, ph.longitude)::numeric, 2)::double precision
           end as distance_km
    from public.pharmacies ph
    where ph.approval_status = 'approved' and ph.is_listed
      and (v_q is null or private.normalize_search(ph.name) like '%' || private.like_escape(v_q) || '%')
      and (v_city is null or private.normalize_search(ph.city) = v_city)
  ) t
  order by t.distance_km nulls last, t.name, t.id
  limit v_limit offset v_offset;
end
$$;

create function public.get_public_pharmacy(p_pharmacy_id uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v jsonb;
begin
  perform private.assert_active_user();
  select jsonb_build_object(
    'id', ph.id, 'name', ph.name,
    'phone', case when ph.show_phone_publicly then ph.phone else null end,
    'address_line', ph.address_line, 'neighborhood', ph.neighborhood, 'city', ph.city,
    'directions', ph.directions, 'opening_hours', ph.opening_hours, 'currency', ph.currency,
    'latitude', ph.latitude, 'longitude', ph.longitude
  ) into v
  from public.pharmacies ph
  where ph.id = p_pharmacy_id and ph.approval_status = 'approved' and ph.is_listed;
  if v is null then
    perform private.fail('not_found');
  end if;
  return v;
end
$$;

create function public.get_public_pharmacy_products(
  p_pharmacy_id uuid,
  p_query text default null,
  p_category_id uuid default null,
  p_limit integer default 20,
  p_offset integer default 0
) returns table (
  product_id uuid, medicine_id uuid, name_ar text, name_en text, brand_name text, strength text,
  dosage_form text, price numeric, currency text, confirmed_at timestamptz, freshness text
)
language plpgsql stable security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_q text := nullif(private.normalize_search(p_query), '');
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
begin
  perform private.assert_active_user();
  if not exists (
    select 1 from public.pharmacies ph
    where ph.id = p_pharmacy_id and ph.approval_status = 'approved' and ph.is_listed
  ) then
    perform private.fail('not_found');
  end if;
  return query
  select pp.id, m.id, m.name_ar, m.name_en, m.brand_name, m.strength, m.dosage_form, pp.price, ph.currency,
         pp.confirmed_at, private.listing_freshness(pp.confirmed_at)
  from public.pharmacy_products pp
  join public.pharmacies ph on ph.id = pp.pharmacy_id
  join public.medicines m on m.id = pp.medicine_id
  where pp.pharmacy_id = p_pharmacy_id and pp.is_available and m.catalog_status = 'approved'
    and pp.confirmed_at >= now() - make_interval(days => private.cfg_int('listing_max_age_days'))
    and (v_q is null or m.search_text like '%' || private.like_escape(v_q) || '%')
    and (p_category_id is null or m.category_id = p_category_id)
  order by coalesce(nullif(m.name_ar, ''), m.name_en), pp.id
  limit v_limit offset v_offset;
end
$$;

-- ---------------------------------------------------------------------------
-- Dashboard
--   * Figures come only from completed sales (orders that were cancelled, rejected or expired never
--     create a sale). Returns/refunds are not part of the MVP, so none are netted out.
--   * Day boundaries use the pharmacy time zone; the week starts on Saturday.
-- ---------------------------------------------------------------------------
create function private.sales_period(p_pharmacy uuid, p_from date, p_to date, p_tz text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('total', coalesce(sum(s.total), 0), 'count', count(*))
  from public.sales s
  where s.pharmacy_id = p_pharmacy
    and s.created_at >= private.local_day_start(p_from, p_tz)
    and s.created_at < private.local_day_start(p_to + 1, p_tz)
$$;

create function public.pharmacy_dashboard(
  p_pharmacy_id uuid,
  p_from date default null,
  p_to date default null
) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_ph public.pharmacies;
  v_tz text;
  v_today date;
  v_from date;
  v_to date;
  v_week_start date;
  v_month_start date;
begin
  perform private.assert_active_user();
  perform private.assert_member(p_pharmacy_id, array['owner', 'manager']::public.member_role[], false);
  select * into v_ph from public.pharmacies where id = p_pharmacy_id;
  v_tz := v_ph.timezone;
  v_today := (now() at time zone v_tz)::date;
  v_to := coalesce(p_to, v_today);
  v_from := coalesce(p_from, v_to - 9);
  if v_from > v_to or v_to - v_from > 365 then
    perform private.fail('invalid_input', jsonb_build_object('field', 'range'));
  end if;
  v_week_start := v_today - ((extract(dow from v_today)::integer + 1) % 7);
  v_month_start := date_trunc('month', v_today)::date;

  return jsonb_build_object(
    'currency', v_ph.currency,
    'timezone', v_tz,
    'today', private.sales_period(p_pharmacy_id, v_today, v_today, v_tz),
    'week', private.sales_period(p_pharmacy_id, v_week_start, v_today, v_tz),
    'last_10_days', private.sales_period(p_pharmacy_id, v_today - 9, v_today, v_tz),
    'month', private.sales_period(p_pharmacy_id, v_month_start, v_today, v_tz),
    'range', jsonb_build_object('from', v_from, 'to', v_to) || private.sales_period(p_pharmacy_id, v_from, v_to, v_tz),
    'daily_series', coalesce((
      select jsonb_agg(jsonb_build_object('day', d.day, 'total', coalesce(t.total, 0), 'count', coalesce(t.cnt, 0)) order by d.day)
      from (select v_from + n as day from generate_series(0, v_to - v_from) n) d
      left join (
        select (s.created_at at time zone v_tz)::date as day, sum(s.total) as total, count(*) as cnt
        from public.sales s
        where s.pharmacy_id = p_pharmacy_id
          and s.created_at >= private.local_day_start(v_from, v_tz)
          and s.created_at < private.local_day_start(v_to + 1, v_tz)
        group by 1
      ) t on t.day = d.day
    ), '[]'::jsonb),
    'best_sellers', coalesce((
      select jsonb_agg(b order by b.quantity desc, b.name)
      from (
        select si.product_id, si.product_name as name, sum(si.quantity)::integer as quantity,
               sum(si.line_total) as revenue
        from public.sale_items si
        join public.sales s on s.id = si.sale_id
        where s.pharmacy_id = p_pharmacy_id
          and s.created_at >= private.local_day_start(v_from, v_tz)
          and s.created_at < private.local_day_start(v_to + 1, v_tz)
        group by si.product_id, si.product_name
        order by sum(si.quantity) desc, si.product_name
        limit 5
      ) b
    ), '[]'::jsonb),
    'listing', jsonb_build_object(
      'available', (select count(*) from public.pharmacy_products pp
                    where pp.pharmacy_id = p_pharmacy_id and pp.is_available),
      'unavailable', (select count(*) from public.pharmacy_products pp
                      where pp.pharmacy_id = p_pharmacy_id and not pp.is_available),
      'stale', (select count(*) from public.pharmacy_products pp
                where pp.pharmacy_id = p_pharmacy_id and pp.is_available
                  and pp.confirmed_at < now() - make_interval(days => private.cfg_int('fresh_days')))
    ),
    'open_requests_count', private.open_request_count(p_pharmacy_id),
    'pending_orders_count', (
      select count(*) from public.orders o where o.pharmacy_id = p_pharmacy_id and o.status = 'pending'
    ),
    'recent_orders', coalesce((
      select jsonb_agg(ro order by ro.created_at desc)
      from (
        select o.id, o.public_ref, o.status, o.subtotal, o.currency, o.created_at, o.customer_name
        from public.orders o
        where o.pharmacy_id = p_pharmacy_id
        order by o.created_at desc
        limit 10
      ) ro
    ), '[]'::jsonb)
  );
end
$$;

-- ====================================================================================================
-- PART 20261011000009_storage_and_function_grants.sql
-- ====================================================================================================
-- Private storage bucket for pharmacy licence documents, and EXECUTE grants for the API surface.

-- ---------------------------------------------------------------------------
-- Storage: bucket `pharmacy-documents`
--   * private, 5 MB, PDF / JPEG / PNG only
--   * object path must be '<auth.uid()>/<file>'
--   * owners may upload and read their own files; admins may read all; nobody may update/delete from the client
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('pharmacy-documents', 'pharmacy-documents', false, 5242880,
        array['application/pdf', 'image/jpeg', 'image/png'])
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

create policy pharmacy_documents_insert_own on storage.objects
  for insert to authenticated
  with check (
    bucket_id = 'pharmacy-documents'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy pharmacy_documents_select_own on storage.objects
  for select to authenticated
  using (
    bucket_id = 'pharmacy-documents'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy pharmacy_documents_select_admin on storage.objects
  for select to authenticated
  using (bucket_id = 'pharmacy-documents' and private.is_admin());

-- ---------------------------------------------------------------------------
-- Function grants
-- Every function in `public` is part of the client API and is callable by signed-in users only.
-- Internal helpers live in `private` and are never granted, except the three used by RLS policies
-- and generated columns. New public functions MUST be reviewed: this migration is the single place
-- where the API surface is declared, and tests/10_tests_security.sql fails if anon can execute any.
-- ---------------------------------------------------------------------------
grant execute on all functions in schema public to authenticated;
revoke execute on all functions in schema public from anon, public;

-- Final sweep of the internal schema (functions created after migration 4 included).
revoke execute on all functions in schema private from public, anon, authenticated;
grant execute on function private.is_admin() to authenticated;
grant execute on function private.is_member(uuid, public.member_role[]) to authenticated;
grant execute on function private.normalize_search(text) to authenticated;
